export const TAROT_DIR = 'assets/tarot/';

export const TAROT = [
  { id: "t00", name: "愚人", en: "The Fool", arcana: "major", suit: null, file: "00.jpg",
    scene: "一个年轻人站在悬崖的最边缘，他仰着头看天，一只手举着一朵白玫瑰，另一只手腕上挂着一个小小的包袱。一只白色的小狗在他脚边跳，像是在咬他的裤脚，又像是在叫他。他穿着花哨的衣裳，像个小丑，又像个王子。悬崖下面有尖石。太阳在他头顶，很大，很亮。",
    up: "那只脚它已经不在地面上了，他不是在“准备跳”，他已经在走了。正位的愚人最核心的感受是：他知道下面是悬崖，但他没有让那个悬崖成为他这一步的主人。他仰着头，他的眼睛看的是天，不是脚下的路。那只小狗在跳，在叫，但它拦不住他。正位时这张牌说的是：你正处在一个“我已经迈出去了，但我还没有落下来”的瞬间，是一种开始，全然信任的新的开始。你手里那朵白玫瑰是“我什么都没带，但我带了这个”，那个包袱小得可怜，里面装不下什么。你不需要更多，甚至不需要往下看。太阳在你头顶，照耀着你，你不需要路，你就是路。",
    rev: "倒过来，世界颠倒了。原本在脚下的悬崖现在压在头顶——所以逆位的时候，不是危险消失了，而是你开始被它压住了。逆位的愚人有两种：一种是你迈出去了，但你低头看了，你的脚缩回来了——你站在悬崖边，你本来已经走了，但你突然看见了下面的尖石，你僵住了；另一种是你根本没迈出去——你站在悬崖边上，你看着天，你举着玫瑰，但你的两只脚都还在地上。你在表演一个要走的人，但你没有走。那只小狗还在跳，但你已经听不见它了。逆位的核心是：你和那个“不管了先走”之间，隔了一个“但是”。你在等一个不会来的安全保证，然后你才肯迈脚。但那张画告诉你：安全保证不在悬崖下面，它在你的脚离开地面的那一瞬间（全然相信自己的那一瞬间）。" },
  { id: "t01", name: "魔术师", en: "The Magician", arcana: "major", suit: null, file: "01.jpg",
    scene: "一个男人站在一张桌子前，一只手高举一根权杖指向天空，另一只手指着地面。桌上放着四样东西：权杖、圣杯、宝剑、星币。他穿着白袍，外面披着红袍。他的头顶是一个无限符号（∞）。他身后是玫瑰和百合的花园。他看着前方，嘴角有一丝笑。",
    up: "关注那两只手的方向。一只指天，一只指地。指“我上面拿到的，我往下面放”。他的身体是一根管道，东西从他头顶进来，从他指尖出去。桌上四样东西，是流经他的，现在它们停在桌上，但他不需要一直握着。正位的魔术师最核心的感受是：“我手里什么都有，但我不需要握着。我只需要指（创造）。”那个∞在头顶，是“无限”，也是“东西从我这里过，不停留”。正位时这张牌说的是：你现在拥有你需要的一切工具，你可以创造一切。它们就在桌上，你不需要再去找了。你只需要举手指天，落手指地，让东西流过去，你只需要让它经过你，它自然就被创造出来了。",
    rev: "倒过来，那只指天的手在下方，那只指地的手在上方。方向反了，接天的口朝下，落地的口朝上，所以他接不到上面，也落不到下面，整根管道卡在中间。逆位的魔术师有两种：一种是“你手里有四样工具，但你不知道该用哪个，你全部抓在手里，哪个也没放下”，你把四样东西全攥在手里，你什么都想做，你什么都做不了；另一种是你在用工具骗人——你举着手，你指着地，你做出那个“我在连接天地”的姿态，但你桌上是空的，或者你桌上放的不是真的。你的白袍底下不是白的。那个∞倒过来，不再是“无限经过我”，而是“我在自己里面打转”。逆位的核心是：你和你的能力之间，断了。要么是你抓得太紧，要么是你演得太假。你没有真的在“让东西经过你”，你在“假装让东西经过你”。" },
  { id: "t02", name: "女祭司", en: "The High Priestess", arcana: "major", suit: null, file: "02.jpg",
    scene: "一个女人坐在两根柱子之间——一根黑色的，标着\"B\"；一根白色的，标着\"J\"。她穿着蓝色的长袍，头上戴着三顶新月组成的冠冕。她的膝盖上放着一卷经书，上面写着\"TORA\"，但被她的袍子遮住了一半。她身后是一块画满石榴的帷幔。她的脚下是一弯新月。她的目光是平视的、安静的、不看你也不看别处的。",
    up: "她不看任何地方。因为她在看一个你看不见的地方。那卷TORA在她膝盖上，被袍子盖住了一半——真理就是这样，只露一半，另一半不给你看，也不需要给你看。正位的女祭司最核心的感受是：她知道真理，但她不会告诉你。不是因为她吝啬，是因为那个东西说出来就变了。那两根柱子是入口，但她不是门，她是坐在门里的人。石榴在身后，是里面还有东西，但你掀不开那块布。正位时这张牌说的是：你心里有一个知道，但你说不出来。你不需要说出来。你只需要坐在那里，让那个知道在你膝盖上待着。它会自己长出来。你不需要翻开那一页，你不需要向任何人解释你看见了什么。你的沉默本身就是答案。",
    rev: "倒过来，书从膝盖上滑下来，脚下的新月也滚到了远处。原本安稳的“知道”开始动摇。逆位的女祭司有两种：一种是“你心里知道，但你把它压得太深了，深到你自己都开始怀疑‘我真的知道吗’”——你开始假装你什么也不知道，你开始假装你没有看见（不能诚实直面自己内在）；另一种是你说了，但那个东西还没长好，一说出口就散了。你把那卷书翻开了，你把TORA念出来了，但你念的时候，那个东西就死了。逆位的核心是：你和你的“内在知道”之间，隔了一层。要么是你把它藏得太深了，深到你够不着了；要么是你把它暴露得太早了，它还没成形就被风吹散了。" },
  { id: "t03", name: "皇后", en: "The Empress", arcana: "major", suit: null, file: "03.jpg",
    scene: "一个女人坐在一张柔软的椅子上，椅子放在一片麦田和花园之间。她穿着饰有石榴图案的白袍，头上戴着十二颗星星组成的冠冕。她一手扶着椅子的扶手，另一只手轻轻搭在膝盖上。她的脚边有一片麦田，麦子已经熟了。她身后是树林，树林里有一条小溪。她的表情是满足的、松弛的、微微含笑的。她的整个身体是向后靠的。",
    up: "她靠在椅背上，像一棵树靠在土里。正位的皇后最核心的感受不是“丰饶”，是“我不需要做任何事，东西就会长”（也指内心的丰盛）。她身后的麦田不必是她亲手种的，就算种了，她也没有站在那里盯着它长。她坐下来了，她休息了，麦子自己熟了。她袍子上的石榴，里面有很多籽——她身体里也有很多东西正在等待。十二颗星在头顶，不是她挣来的，是她本来就在星星下面。正位时这张牌说的是：你现在不需要努力，不需要推，不需要“做”。你需要坐下来，靠下去，让你的身体放松。你身体里的那些东西——创意、爱、生命力——它们不需要你盯着才会长。你越不看，它们越长。你就坐在那里，让麦子自己熟。",
    rev: "倒过来，星星从冠冕上滑落，麦田翻到上方，像整片天空要压下来。原本的“靠”变成了“陷”。逆位的皇后有两种：一种是“你坐下来了，但你坐不住了”——你想靠，但你的身体是紧的，你的眼睛在看麦田，你在数“麦子够不够多，熟没熟”，你无法真的松弛。你坐在那里，但你的脑子在站着；另一种是你给了太多，你空了——你的袍子上的石榴裂了，籽掉了一地。你一直在把果实给别人，但你自己的土是干的。那条小溪在你身后，但你没有回头去喝。逆位的核心是：你和你的“丰饶”之间，断了。你要么在强迫自己产出，要么你已经产出到干涸了。你没有在“坐”，你在“耗”。" },
  { id: "t04", name: "皇帝", en: "The Emperor", arcana: "major", suit: null, file: "04.jpg",
    scene: "一个男人坐在一把石质的、方方正正的宝座上。宝座上刻着四个羊头。他穿着红色的袍子，里面是铠甲。他一手持一根权杖（顶端是安卡符号），另一只手搭在扶手上。他的白胡子很长。他身后是荒芜的山，没有树，没有水，只有石头。他的目光是直视前方的，嘴唇紧抿。",
    up: "那把椅子的形状是方的，是硬的，是石头的。没有靠垫，没有花，没有葡萄藤。他坐上去就不是用来舒服的，是用来坐稳的。正位的皇帝最核心的感受是：“我不需要柔软。我需要的是不动。”他身后的山是秃的，没有皇后那片麦田，没有树林，没有小溪。只有石头。他不需要那些。他需要的是边界，是骨头，是能让一切不散架的结构。他的铠甲在袍子底下——他穿着柔软的外衣，但里面是硬的。正位时这张牌说的是：你现在需要立一个规矩，定一个边界，做一个不可动摇的决定。你不需要解释，不需要温柔，不需要“但是”。你不欠任何人一个柔软的理由。你只需要坐在那里，不动。你不靠任何东西，因为你自己就是那个靠。",
    rev: "倒过来，石椅裂开，羊头朝下——原本的“不动”塌成了两种：一种是你不让别人动，一种是你自己动不了。 第一种是暴君：你的规则不是为了保护，是为了控制。你坐在那把椅子上，但你不允许任何人站起来，不允许任何东西长出来。你的山是秃的，不是因为“我不需要柔软”，是因为你把所有柔软的东西都砍了。 第二种是你坐不住了：你的石椅在晃，你的铠甲太重了，你的白胡子在抖。你发现自己维持那个“不动”的姿势维持了太久，你的关节僵了，你想站起来，但你不知道站起来之后你还是不是皇帝。 逆位的核心是：你的“稳”和“僵”之间，那条线你看不清了。你是在保护，还是在压制？你是在立规矩，还是在害怕变化？" },
  { id: "t05", name: "教皇", en: "The Hierophant", arcana: "major", suit: null, file: "05.jpg",
    scene: "一个穿着红色和白色法袍的男人坐在两根灰色柱子之间。他一手举起，两根手指朝天，另一只手拿着一个三重十字权杖。他的脚下跪着两个人，穿着不同颜色的袍子。他头上戴着三重冠冕。他的表情是平静的、庄严的、微微向下看的。",
    up: "注意那两根手指，两根手指竖起来，像是在说“我要说一个东西了”。正位的教皇最核心的感受不是“宗教”，而是“有人比你先走过这条路，他回来告诉你怎么走”。那两个人跪着，不是被强迫的，是他们选择跪下来听。他们穿着不同的衣服，说明他们不一样，但他们都跪着，都在听同一个人说同一句话。正位时这张牌说的是：你现在需要听。不是听你自己，是听一个走过的人。你需要一个结构、一个传统、一个“别人已经验证过的路”。你不需要自己发明轮子。你跪下来，不是因为你弱，是因为你选择让一个经验比你多的人告诉你下一步。你不是把力量交出去，而是暂时让一个更大的结构托住你。那两根手指在说：“听好了，是这样的。”",
    rev: "倒过来，两根手指朝下，跪着的人站了起来。不再有人想听了，或者那个说话的人已经不再可信。逆位的教皇有两种：一种是“你跪了很久了，你的膝盖疼了，你站起来了，你发现那个三重冠冕下面的人也是个人，他也会说错”——你不再需要那个“权威的声音”了，你要自己走；另一种是你在用那个结构压别人——你不是在教，你是在要求别人跪。你的“传统”不再托人，只要求人；你的“经验”不再分享，只用来让人闭嘴。逆位的核心是：你和那个“更高的声音”之间，关系变了。要么是你不再相信它了，要么是你把它变成了控制别人的工具。你需要问自己：我是在听，还是在要别人听？你站起来之后，不必把整个结构都推倒，但你要知道，你的膝盖现在属于你自己。" },
  { id: "t06", name: "恋人", en: "The Lovers", arcana: "major", suit: null, file: "06.jpg",
    scene: "一男一女面对面站着，都没有穿衣服。他们之间上方有一个天使，翅膀张开，双手向下伸出，像是在祝福，又像是在看着他们。女人身后是一棵树，树上有一条蛇。男人身后是一棵树，树上有一团火。远处是一座山，山顶是尖的。天空是明亮的。他们的身体朝向彼此，但他们的目光不是对视的——女人看着天使，男人看着女人。",
    up: "为什么他们都没有穿衣服？因为这不是情欲的裸，是“我站在你面前，我什么都没有了”的裸，敞开心扉没有任何限制的裸。没有铠甲，没有袍子，没有星币，没有剑。正位的恋人最核心的感受不是“爱情”，是“选择”。那个天使在上面，但他的手是向下伸的——他不是在拉你上去，他是在说“你选吧”。女人看的是天使，不是男人——她在看那个更高的东西，她在问“我应该吗”。男人看着女人——他已经做出了选择，他的目光已经落在她身上。那两棵树不一样：她身后是蛇，是“如果你选了这个，你会知道一些你之前不知道的东西”；他身后是火，是“如果你选了这个，你会被点燃”。正位时这张牌说的是：你面前有一个选择，它不是“对或错”，是“我赤裸地站在这里，我选择这个”。你不需要天使告诉你怎么选。你需要自己站在那里，裸着，然后选。你选的不是那个对象，而是你选完之后愿意成为的那个自己。",
    rev: "倒过来，天使在下方，两棵树在上方。你好像站在选择中间，却动弹不得——不是不想选，是选哪边都像撕裂。逆位的恋人不是“你不爱了”，是“你站在那里，但你转不了身”。你的身体朝着这个选择，眼睛却看向你没有选的那一边。你的选择是撕裂的。那个天使不再在上面祝福你了，他在下面，他的翅膀收着，他的脸是背过去的。逆位的核心是：你和你的选择之间，有一个“但是”。你选了，但你没有完全选择你所选择的。你的一只脚在走，另一只脚还在原地。你没有裸着站在那个选择里，你穿着衣服，你在藏。你不是怕选错，是怕选完之后必须承担的后果。" },
  { id: "t07", name: "战车", en: "The Chariot", arcana: "major", suit: null, file: "07.jpg",
    scene: "一个年轻的战士站在一个方形的战车上，手持一根权杖。他头顶有一个星形的华盖。战车由两只狮身人面像拉着——一黑一白。它们没有缰绳。他身后是一座城市，有城墙和塔楼。他穿着铠甲，但他的肩膀上画着月亮。他的表情是坚毅的、向前看的。",
    up: "最让人紧张的是：没有缰绳。那两只狮身人面像一黑一白——它们之间没有绳子连着，它们和战车之间也没有。战车中的人在用意志拉着它们。正位的战车最核心的感受不是“冲”，是“我在用我的全部注意力让两个相反的东西往同一个方向走”。黑和白它们是两股方向不同的力，你要让它们同时往前，你不能偏，你一偏，车就翻了。身后的城市是“你离开的地方”，你没有回头。正位时这张牌说的是：你正在驾驭一个需要你把全部意志集中起来的局面。你手里那根权杖不是武器，是方向盘。你不需要打它们，你不需要喊，你只需要站在那里，看着前方，不让任何一边偏。你的铠甲是硬的，但你的肩膀上有月亮——你是柔的，你不是铁做的。你在用你里面那个不硬的东西，去做一件很硬的事。",
    rev: "倒过来，两只狮身人面像往两个方向走了，车在原地转。它们的力不是向前，是向外撕扯。你越用力，车越不动。逆位的战车不是“你翻车了”，是“你一直在拉，但你已经不知道你要去哪了”。那两只一黑一白的力越来越往两边扯，你的权杖举着，但你不知道该指向哪边。你身后的城市越来越远了，但你前面没有目的地。你在动，但你没有在走。逆位的核心是：你的意志在，但你的方向没了。你在用力，但那个力是散的。你不需要更用力，你需要停下来，问自己：我到底要去哪？问完这个问题，你才可能重新握住那根权杖" },
  { id: "t08", name: "力量", en: "Strength", arcana: "major", suit: null, file: "08.jpg",
    scene: "一个穿着白袍的女人，正在轻轻地合上一只狮子的嘴。她的手放在狮子的上下颚之间，不是掰，是合。她的头顶有一个无限符号（∞）。她身后的背景是柔和的山丘和天空。她的表情是安静的、专注的、微微含笑的。狮子是金色的，它的眼睛是闭着的，或者说，它正在被她合上眼睛。她身上有花环。",
    up: "她在用手，轻轻地，把那张嘴合上。正位的力量最核心的感受是：“我不需要比你强，我只需要比你安静。”那只狮子不是被制服了，是被安抚了。它的眼睛在闭，它的嘴在合，它不是输了，它是累了，终于可以休息了。那个∞在头顶，和魔术师头上的一样——但在这里它不是“流过”，是“她有的是时间”。正位时这张牌说的是：你面前有一个巨大的、凶猛的、让你害怕的东西——可能是你的恐惧，可能是你的愤怒，可能是另一个人。你不需要打赢它。你需要走过去，把手放在它的嘴上，轻轻地合上。你不需要喊，不需要用力。你只需要先让自己安静下来，安静到它愿意在你手里闭上眼睛。",
    rev: "倒过来，狮子的嘴张开了，女人的手在往后缩。原本温柔的“合”变成了两种：一种是你不敢伸手，一种是你伸手去压。 第一种是“你面对的那个东西太大了，你的手在抖，你开始想跑了”——你的白袍在风里飘，你的花环松了，你发现自己没有你以为的那么安静。你开始怀疑“我真的能合上那张嘴吗”。 第二种是你用力了——你不是在“合”，你是在压。你用蛮力去压那个东西，你压住了它的嘴，但它的眼睛是睁着的，它在看着你，它在等你松手。 逆位的核心是：你和你的“柔软的力量”之间，断了。你要么在逃，要么在用硬的方式去做需要柔的事。你不需要更用力，你需要更安静，安静到那只狮子重新相信你的手。" },
  { id: "t09", name: "隐士", en: "The Hermit", arcana: "major", suit: null, file: "09.jpg",
    scene: "一个老人站在山顶上，穿着灰色的长袍，连帽戴着。他一手拄着一根长杖，另一只手举着一盏灯，灯里有一颗六角星在发光。他微微低着头，看着灯，不看前方，不看下方。他身后是更多的山和灰色的天空。他的脸藏在帽子的阴影里。",
    up: "他不看远方，他举着灯，灯照他自己的路。正位的隐士最核心的感受是：“我需要一个人待一会儿，我需要看看我手里这盏灯。”那颗六角星在灯里，很小，但很亮。它不是太阳，不是月亮，是一盏只够照亮你脚下一步的灯。他不需要看见整座山，他只需要看见这一步。一切都是灰的，只有那颗星是亮的。正位时这张牌说的是：你现在需要退开。不是永远退开，是退开一会儿。你需要把那盏灯举起来，低头看看你手里有什么。你不需要答案，你需要安静，安静到能听见自己的脚步声。你不需要别人陪你，你不需要别人看见你。你只需要站在你的山顶上，举着你的灯，看着那颗星。",
    rev: "倒过来，那颗星的光掉到下面，灯快灭了，你开始站不稳。逆位的隐士有两种：一种是“你一个人待太久了，你开始分不清‘我需要安静’和‘我在逃避’”——你的灰色袍子变成了你的皮肤，你忘了袍子底下还有一个你。你的灯举着，但你不再看那颗星了，你在看黑暗，你开始觉得黑暗比光更真实；另一种是你拒绝退出来——你明明需要一个人待着，需要安静，需要看看自己的灯，但你不敢。你怕一旦停下来，你就不知道自己是谁了。所以你继续走，继续不举灯。逆位的核心是：你和你的“独处”之间，关系不对了。要么你困在了里面，要么你逃在了外面。你需要重新找到那个节奏——我举着灯，只看一步，然后走一步。你不需要把整座山照亮，你只需要让那颗星重新亮起来。" },
  { id: "t10", name: "命运之轮", en: "Wheel of Fortune", arcana: "major", suit: null, file: "10.jpg",
    scene: "一个巨大的轮子悬在天空中央，没有人在转它。轮子上有四个符号（炼金术符号），轮子外面有四个有翼的生物在读书（人、鹰、牛、狮）。轮子上有三个\"人形\"——一个在顶部，一个在上升的一侧，一个在下降的一侧。天空是深蓝色的，云是黄色的。",
    up: "没有人推那个轮子，它自己在转。正位的命运之轮最核心的感受是：“这个东西不是你在转，你只是上面的人。”但你不是没有选择——你只是不能选择轮子往哪转，只能选择自己怎么待在轮子上。那四个有翼的生物在读书，它们在看着它转。它们是“这件事本来就是这样”的见证者。正位时这张牌说的是：你正在经历一个你无法控制的转变。不是因为你做错了什么，也不是因为你做对了什么，是轮子到了那个位置。你不需要推，不需要拉，不需要理解。你只需要在上面待着，保持平衡。你越抵抗，它越颠簸。它会转过去的。",
    rev: "倒过来，轮子像卡住了，或者开始反转。你被那种“停不下来”的感觉甩动，或者你想从轮子上跳下去。逆位的命运之轮有两种：一种是你知道自己在往下走，你不想，但你停不了；另一种是你站在轮子外面，看着它转，说“我不要上去”，但你发现你已经在上面了，你只是假装自己不在。逆位的核心是：你和“变化”在较劲。你试图让轮子停，或者让它只往好的方向转。但它不听你的，它从来不听任何人的。你能做的不是让它停，而是承认你在上面，然后停止和自己较劲。你越抓，它越响。" },
  { id: "t11", name: "正义", en: "Justice", arcana: "major", suit: null, file: "11.jpg",
    scene: "一个女人坐在两根柱子之间（和女祭司类似，但柱子是灰色的、素的）。她一手持一把直立的剑，另一只手拿着一架天平。她的眼睛是睁着的，直视前方。她穿着红色的袍子，头上戴着方形的冠冕。她的表情不是温柔的，是平的——没有笑，没有怒，就是平的。她身后是一块紫色的布幔。",
    up: "那把剑不是用来砍的，它是用来量的。正位的正义最核心的感受不是“你被审判了”，是“你正在看着事情本来的样子”。那两根柱子是灰的，不是黑也不是白——事情没有那么多戏剧，它就是它。那架天平在她手里，但它是平的——不偏不倚。她的眼睛是睁着的——正义看着你。她知道你是谁，她看着你的眼睛，然后她称。正位时这张牌说的是：你正在面对一个需要你完全诚实的时刻。不是对别人诚实，是对自己诚实。你需要把那架天平拿出来，把你手里的东西放上去，看看它到底重不重。那把剑不是惩罚，是切割——把“我以为的”和“实际是的”切开。你不需要害怕。你只需要看着，然后承认。承认了，你才能重新找回平衡。",
    rev: "倒过来，那把剑歪了，天平也歪了。你称不准了，或者你不想再称了。逆位的正义有两种：一种是你在自欺。你把重的东西说成轻的，把轻的说成重的，你假装那架天平是平的，但你自己知道它歪了；另一种是你被不公平地称了，你被一个不公正的标准审判了。你睁着眼，你看着那个歪的天平，你说不出来，因为“正义”不站在你这边。逆位的核心是：你和“真相”之间，有一个偏差。要么是你自己把天平弄歪了，要么是别人弄歪了。不管天平是被谁弄歪的，你都需要先承认它现在没有平。然后问自己：我敢不敢看那架天平本来的样子？" },
  { id: "t12", name: "倒吊人", en: "The Hanged Man", arcana: "major", suit: null, file: "12.jpg",
    scene: "一个男人被一只脚倒吊在一根T形的木架上。他的另一只脚弯曲，交叉在另一条腿后面。他的双手背在身后。他的头上有一个光环。他的表情不是痛苦的，是平静的，甚至是微微沉思的。他的眼睛是睁着的。他穿着蓝色的裤子和红色的上衣。背景什么都没有，只有那根木架和天空。",
    up: "他倒着，但他的脸是松的。不是忍痛的那种松，是真的松。他的眼睛是睁着的，他在看。正位的倒吊人最核心的感受是：“我停下来了，而且我发现倒着看，看到的东西不一样。”他没有挣扎，没有试图解开绳子。他就那么吊着。他的一只脚被绑住了，另一只脚是自己弯的——他自己选择了这个姿势。那个光环原本在头顶，现在悬在下方，像他的内在光亮在倒置中反而被点亮了。正位时这张牌说的是：你现在需要停下来，你需要换个角度看这件事。你一直正着看，你看不见。你倒过来，你什么都不做。然后你会看见一些你正着看永远看不见的东西。你不是被吊在那里，你是让自己悬在那里，好看得更清楚。",
    rev: "倒过来，他的身体看似正了，但那只脚还挂在绳子里。你不想再吊了，但你还没有完全下来。逆位的倒吊人有两种：一种是“你吊了太久了，你开始觉得‘我是不是在浪费时间’，你开始挣扎，你想下来”——你的光环暗了，你的脸不再是平静的，你开始烦躁，你开始觉得这个“停下来”是没有意义的，好像只是在浪费时间，而不是在看见什么；另一种是你拒绝倒过来——你明明需要停，需要换一个角度看，但你拒绝。你正着站在那里，你看着那根木架，你说“我不需要那个”，但你心里知道你需要。逆位的核心是：你和“停下来”之间，在较劲。你要么吊太久了开始慌了，要么你根本不肯吊。你需要问自己：我是在真的“倒着看”，还是我只是在“等着”？这两件事不一样。" },
  { id: "t13", name: "死神", en: "Death", arcana: "major", suit: null, file: "13.jpg",
    scene: "一个穿着黑色铠甲的骷髅骑在一匹白马上，手里举着一面黑色的旗，旗上有一朵白色的玫瑰。马在走，不是跑。马脚下有一个倒下的国王、一个主教、一个少女、一个孩子。远处是太阳正在落下，地平线上有两座塔。天空是灰黑色的。",
    up: "那匹马只是在走，它不急，骷髅也不急。那面旗只是举着的。正位的死神最核心的感受不是“死亡”，是“它来了，而且它不跟你商量”。那个国王倒下了，他的权杖在地上，他的冠冕歪了——你的权力在它面前没有用。那个主教倒下了，他的法袍在地上——你的信仰在它面前不能挡。那个少女和那个孩子还在站着，但他们在看着它。他们没有倒下，但他们的脸是白的。纯真和未来不会被收走，但它们必须看着旧的结束。那面黑旗上有一朵白玫瑰——和愚人手里的白玫瑰是同一朵。它经过了愚人之旅，现在被死神收走，但不是毁掉，是接过去。正位时这张牌说的是：有什么东西正在结束。那匹马已经走到你面前了，那面旗已经举到你眼前了，它经过之后，太阳会落下去，但它又会重新升起。死神不是来抢走你，是来拿走你已经不再需要的东西。",
    rev: "倒过来，马停下了，旗垂下来。它来了，但你不让它过，或者你一直假装它没有来。逆位的死神有两种：一种是“那个该结束的东西，你不让它结束”。你觉得如果你不松手，它就不会真的走。但它已经走了。你抱着的只是一个形状。你需要松手，不是因为你不爱了，是因为你抱着的已经不是它了；另一种是你急着让一个东西死，其实它还没走完。你受不了那个不确定的阶段，所以你提前判了它死刑。但死神还没来，是你自己在挖坑。 逆位的核心是：你和“结束”之间的关系错了。你不是太迟放手，就是太早下手。你不需要求它回来，你只需要承认它已经走了。或者承认，它还没到该走的时候。" },
  { id: "t14", name: "节制", en: "Temperance", arcana: "major", suit: null, file: "14.jpg",
    scene: "一个天使站在一条小溪中，一只脚在水里，一只脚在岸上。天使手里拿着两只杯子，正在把水从一只杯倒向另一只杯。水在两只杯之间流动，但没有洒。天使的额头上有一个三角形符号。天使的翅膀是展开的。远处有一条小路通向两座山之间，山之间有一个发光的冠冕。天空是清晨的颜色。",
    up: "水从一只杯到另一只杯，不是倒完了，是一直在倒。它不是“倒一次”，是持续的、流动的、不停的。正位的节制最核心的感受是：“让两样东西之间保持流动，我不让任何一边满，也不让任何一边空。”那只脚在水里，那只脚在岸上——你不全在任何一个地方。你一半在感受里，一半在现实里。那个远处的冠冕在两座山之间，是“你要去的地方”，但你不急。你先把水倒好。正位时这张牌说的是：你现在需要做的不是选择一边，是让两边流动起来。你不需要在“要么这样，要么那样”里选一个。你需要让两边之间有一道水流通过。你不急。你的翅膀是展开的，但你没有飞。你站在那里，倒水。这个动作本身就是目的。那个远处的冠冕不会跑掉，它就在两座山之间等你。",
    rev: "倒过来，水洒了，杯子的高低对不上了，原本的“流动”断了。逆位的节制有两种：一种是“你倒得太快了，水溢出来了”——你试图让两样东西平衡，但你太急了，你一下子倒太多，洒了，你慌了，你试图用另一只杯去接，但接不住；另一种是你不再倒了——你把两只杯都放下了，或者你把一只杯扣过来了。你不再让东西流动了。你要么全在这只杯里，要么全在那只杯里。逆位的核心是：你和“流动”之间，断了。你要么太急了，要么完全停了。你需要重新找到那个“慢慢地、持续地、不洒地倒”的节奏。哪怕一开始只是一滴一滴，也要让水重新开始流动。" },
  { id: "t15", name: "恶魔", en: "The Devil", arcana: "major", suit: null, file: "15.jpg",
    scene: "一个巨大的、有角的、有翅膀的黑暗生物蹲在一个黑色的立方体上。它一手指天，一手指地（和魔术师一样的手势）。它的脚下有两条链子，链子分别拴着一男一女。那两个人也是赤裸的，头上有角和尾巴。但链子是松的——松到他们可以把链子从头上取下来。他们低着头，不看对方，也不看恶魔。他们身后是黑色的背景。",
    up: "两条链子是松的，圈大得可以从头上取下来。但他们没有取。正位的恶魔最核心的感受是“你以为你被锁住了，但你没有。你只是相信了那个锁。”那个恶魔的手势和魔术师一模一样，但含义完全相反——魔术师让能量流经，恶魔把能量钉住。那两个人不看对方，也不看恶魔。他们低着头，像在数自己的影子。他们不知道链子是松的，或者他们知道，但他们不敢试。正位时这张牌说的是：你被一个东西拴着——可能是一段关系、一个习惯、一个恐惧、一个“我就是这样的人”的信念。你觉得你走不了。但你低头看看那条链子。它是松的。你随时可以把它从头上取下来。你没有取，不是因为取不下来，是因为你害怕取下来之后你不知道自己是谁。",
    rev: "倒过来，恶魔被翻到下面，链子拖在地上。你开始拉那条链子，或者刚把圈从头上推出来。逆位的恶魔是“你正在动那条链子”。你把手伸到头上，你摸到了那个圈，你开始往外推。它很涩，因为很久没有动过了，你的脖子被磨出了印子。但你在推了。那个恶魔还在，它没有消失，但你不再蹲在它下面了。你站起来了。逆位的核心是：你正在从那个“我以为我走不了”里往外走。你还没有完全走掉，你的脖子上还有链子的印子，但你的头已经出来了。你终于看见了：那个圈从来就是松的，只是你第一次真的去推它。" },
  { id: "t16", name: "塔", en: "The Tower", arcana: "major", suit: null, file: "16.jpg",
    scene: "一座高塔被一道闪电击中，塔顶的冠冕被炸飞了。两个人从塔上坠落，一个头朝下，一个脚朝下。火焰从塔的窗口中喷出。天空是漆黑的，闪电是白色的。塔建在一块岩石上。下面是黑暗的、什么都没有的空间。",
    up: "两个人在空中，不在塔上了。他们已经出来了。正位的塔最核心的感受是“那个你一直在里面的东西，突然没有了”。你在那个塔里待了很久了，你把它建得很高，还给它戴了冠冕，你以为它是你的，你以为你在里面是安全的。然后闪电来了。没有预兆，没有商量，冠冕飞了，墙裂了，你从里面被抛出来了。你现在在空中，你什么都抓不住。正位时这张牌说的是：你正在经历一个突然的、不可挽回的、你无法阻止的崩塌。不是慢慢的瓦解，是一瞬间的“没了”。你不需要理解为什么，你不需要在坠落的时候试图抓住什么。你不需要在空中就找到答案。你会落地，然后从新的地面站起来。",
    rev: "倒过来，闪电被压在下面，塔还在上面。崩塌不再从外面来，而是从里面往外顶；或者你早就看见闪电了，只是赶紧关上了窗。逆位的塔有两种：一种是“你看见闪电来了，你拼命用身体堵住窗口，你告诉自己‘不会倒的，不会倒的’”——你在用你的全部力气维持一个已经在裂的结构。你知道它要倒了，但你不允许它倒；另一种是它已经倒了，但你不承认——你站在废墟上，你说“这还是一座塔”，你假装那个冠冕还在，你假装墙还是完整的，甚至不敢看自己脚下已经全是碎石。逆位的核心是：你在抵抗一个已经发生的崩塌。闪电已经劈了。塔已经裂了。你不需要再堵了。承认它倒了，你才能从废墟里真正走出来。" },
  { id: "t17", name: "星星", en: "The Star", arcana: "major", suit: null, file: "17.jpg",
    scene: "一个赤裸的女人跪在水边。她一手拿着一只壶，把水倒进池塘里；另一手拿着另一只壶，把水倒在土地上。她身后是一棵大树，树上有一只鸟。天空中有八颗星——七颗小的围绕着一颗巨大的、有八个角的星。那颗大星是黄色的。她的脸是微微仰着的，看着星，但不是在祈求，是在看着。天空是深蓝色的，很安静。",
    up: "她在倒水，倒给两个地方。她不选择给谁，她是两边都给。正位的星星最核心的感受是：“我把我的东西倒出去了，我不知道它会不会有用，但我倒了。”她是裸的——在经历了塔的崩塌之后，她什么都没有了，她只有这两只壶和壶里的水。正位时这张牌说的是：你正在经历一个“我什么都没有了，但我还有一点什么”的时刻。那一点什么不多，就是壶里那点水。你把它倒出去，不是给谁，是给。你不需要知道它流到哪里去了，你倒给任何接得住的地方。那颗星在那里，它不会灭，你只需要知道它在。你不是在等天亮，你是在夜里继续倒水。",
    rev: "倒过来，壶里的水开始往回流，星被压在下面。原本顺畅的“给”，突然变得困难。逆位的星星有两种：一种是“你的壶空了”——你倒了太久了，你给池塘也给了，给土地也给了，你的壶里什么都没有了。你跪在水边，但你没有水可以倒了。你仰着头看那颗星，但你心里在想“它还在吗？它真的在吗？”；另一种是你把壶抱在怀里，说“这是我最后一点了，我不能给”。你跪在水边，不再把水给出去。逆位的核心是：你和“给出去”之间，断了。你要么空了，要么你不敢再给了。你需要看看那颗星。它还在。它没有因为你不看就灭了。你只需要重新把壶倾斜一点点，让水愿意再出来。" },
  { id: "t18", name: "月亮", en: "The Moon", arcana: "major", suit: null, file: "18.jpg",
    scene: "一轮巨大的满月挂在天空中，月亮里有一张脸。月亮下方是一条蜿蜒的路，路两侧各有一座塔。路的起点有一只狗和一只狼在对着月亮叫。路的前方是一只龙虾从水中爬出来。路通向远方的群山。整个画面是深蓝色的、银色的、模糊的。",
    up: "那条路你看不见尽头，它弯着，绕着，消失在群山之间，你不知道它通向哪里。正位的月亮最核心的感受是“你看不清，而且你必须在看不清的状态下走”。月亮的光不是太阳的光——它把所有东西都照成银色的、模糊的、不确定的。那只龙虾从水里爬出来——有什么东西正在从你潜意识深处浮上来，你之前没有看见它，它现在爬出来了。狗在叫，是那个被规训的你；狼在叫，是那个想挣脱的你。它们都在对着月亮喊。正位时这张牌说的是：你正在走一段你看不清的路。你不需要看清，你只需要走。那个从水里爬出来的东西，你不需要马上认识它，让它爬出来就好。月亮会落的，天也会亮的，但现在还不是亮的时候。你现在在银色的光里走，你走就是了。月亮不会因为你看不清就消失，也不会因为你看清就加快。",
    rev: "倒过来，月亮被翻到下面，那张脸不再悬在头顶。你开始从雾里分辨出一些轮廓，或者你拒绝继续在模糊里耗着。逆位的月亮是“你开始分得清哪些是真的，哪些是你自己加上去的限制性信念”。那些银色的、模糊的东西，你开始看见它们的形状了。那只龙虾还在爬，但你不那么怕了，它没有你想象的那么大。那条路还是弯的，但你看见了下一个弯。逆位的核心是：雾在散。你能看见两座塔之间的距离了，你能看见那条路至少下一步是往哪拐的了。你不需要看见终点，你只需要看见下一步。你不需要等到天亮才走，你只需要借着现在这点光，走下一步。" },
  { id: "t19", name: "太阳", en: "The Sun", arcana: "major", suit: null, file: "19.jpg",
    scene: "一个巨大的、有脸的太阳挂在天空中央，光芒四射。太阳下方，一个赤裸的小孩骑在一匹白马上，手里举着一面红旗。小孩张着嘴，像是在笑，又像是在喊。马在走，不是跑。小孩身后是一片向日葵花田，向日葵很高，比小孩高。远处是一堵灰色的墙。天空是明亮的黄色。",
    up: "正位的太阳最核心的感受是：“你不需要理由就可以开心。”那个小孩是裸的，他什么都没有，没有衣服，没有武器，没有星币。他骑在马上，举着一面红旗，是“我在这里”的旗。向日葵在他身后，它们全部朝着太阳。向日葵没有想过“我该不该朝那边”，它们只是朝。那堵灰色的墙在远处，但它在后面，不在前面。正位时这张牌说的是：你现在可以开心了。不需要“因为什么”而开心，不需要“终于得到了什么”才开心。那个孩子张着嘴，不是为了宣布什么，只是因为他本来就会笑。",
    rev: "倒过来，太阳被压在下方，小孩的嘴闭上了，旗子也垂着。逆位的太阳是“你开心了，但你不允许自己开心”。你骑在马上，太阳在你头顶，向日葵在你身后，但你的嘴是抿着的。你在想“我是不是太高兴了”“我是不是应该担心点什么”“别人还在受苦我怎么能这样”。你把自己的太阳调暗了。你给自己加了一堵灰色的墙，但那堵墙本来在远处的，你把它搬到了面前。逆位的核心是：你在挡自己的光。不是光不在，是你把手伸到眼前，挡住了。你不需要等一个理由才能开心。你不需要等所有人都好了才能笑。你现在就可以把墙推回远处，让自己重新成为那个不害怕笑的人。" },
  { id: "t20", name: "审判", en: "Judgement", arcana: "major", suit: null, file: "20.jpg",
    scene: "一个天使在天空中央吹着一支长长的号角，号角上挂着一面白底红十字的旗。下方是一片灰色的大地，大地上有许多棺材，棺材里的人正在站起来——有男人、女人、孩子。他们张着手臂，仰着头，看着天使。他们的身体是灰色的，但他们的脸是朝上的。远处是山和水。",
    up: "那些棺材是打开的，是从里面推开的，那些人是自己站起来的。正位的审判最核心的感受是“你听见了一个声音，然后你决定站起来了”。那个号角在响，你听见了，你选择这是叫你的，你从那个你躺了很久的地方站起来。你的手臂张着，不是拥抱，是“我在这里，我出来了”。即使你的身体还是灰的，即使你还没有变成新的样子，你还是可以出来。正位时这张牌说的是：你正在经历一个“我听见了，我要起来了”的时刻。不是别人拉你起来的，是你自己推开了那个盖子。你不需要准备好，不需要“等我变好了再出来”。号角声不是叫你去哪里，只是叫你起来。方向可以以后再找。",
    rev: "倒过来，号角被压在下方，那些人还躺在棺材里。你听见了，但你没有起来；或者你起来了，但你又躺回去了。逆位的审判有两种：一种是你不想出来。你在里面待了太久了，你习惯了那个黑暗，你习惯了那个“躺着”的姿势。外面有光，但你不想看。你假装你没有听见；另一种是你站起来了，但你不知道往哪走。你站了起来，但四周太亮了，你一时分不清自己站在哪里。逆位的核心是：你和那个“起来”之间，有一个犹豫。你要么不想起来，要么起来了但不敢走。你需要问自己：我是在等一个更确定的信号，还是只是害怕站起来之后的世界？号角不会停，但你也可以选择下一声再起来。" },
  { id: "t21", name: "世界", en: "The World", arcana: "major", suit: null, file: "21.jpg",
    scene: "一个赤裸的女人在一个巨大的椭圆形花环中跳舞。她双手各持一根权杖，一上一下。她的身体是扭动的、流动的、正在旋转的。花环外面有四个有翼的生物（和命运之轮一样：人、鹰、牛、狮）。她的表情是闭着眼的，或者微微仰着的。她的身体是完整的、松弛的、有力的。背景是淡蓝色的天空。",
    up: "她的身体是在扭动的，一上一下，一前一后，她在椭圆里转圈。正位的世界最核心的感受是：“我到了，但我不是停下来的，我是在动的。”她闭着眼，不是因为她不看，是因为她不需要看了，她的身体知道往哪转。她是裸的，但不再是因为什么都没有，而是因为不再需要遮藏。两根权杖在手，一上一下，阴与阳，对与错，她不需要更多了。正位时这张牌说的是：你到了一个完整的地方。不是完美，是完整（圆满）。你走过了所有的牌，你从愚人走到了这里，你不需要再走了，你不需要再找什么了。在这个花环里转着，你的身体是松的，你可以在这里待一会儿。这里不是终点，是你终于可以重新出发的地方。",
    rev: "倒过来，女人的身体还在转，但她的重心偏了。你差一点就到了，但你没有完全进去。逆位的世界有两种：一种是“你站在花环的边上，你的一只脚在里面，一只脚在外面”——你没有让自己完全进去，你留了一只脚在外面，像是随时准备走。你不允许自己完全地、彻底地、毫无保留地存在；另一种是你到了，但你不知道到了——你在花环里转着，但你睁着眼，你在找出口，你在想“下一个是什么”，你到了，但你不相信，你觉得自己应该再走一圈，再确认一下。逆位的核心是：你和“完成”（圆满）之间，有一个“但是”。你要么差一步没有进去，要么进去了但不相信。你需要闭上眼睛，让你的身体转。你不需要确认，你到了。你到了之后，也不是结束，而是下一个开始。 鱼末白   大阿尔卡纳愚人之旅： 他带着婴儿般的天真纯粹，全然的出发开始自己的旅程； 他发现了自己有创造一切、体验一切、感受一切的能力； 他听见了内在静默中的答案； 因此他内心丰盛； 他建立了内在的秩序，因此如如不动； 他想听前辈讲述的真理； 他做了一个纯粹的选择； 他用意志力去做想做的事； 他用内心力量直面了生存恐惧； 他跟随内心指引一个人独处； 他全然放手顺应自然命运； 他诚实面对自己看清自己； 他学会了换了个角度看世界； 于是经历了一次彻底的结束； 然后他学会了让一切流动； 才明白他其实被欲望和内心恐惧困住了很久； 他让虚假的旧我彻底崩塌； 新的他在废墟中发现希望； 他走了一段看不见尽头的路； 他明白了幸福与开心本无需顾虑； 他听见内我在召唤他，无需改变，此刻就是新的一切； 于是他感受到了圆满，一切本就圆满； 然后他又站在悬崖边上， 手里还是那朵白玫瑰， 这次他低头看了一眼下面， 他还是走了。 小阿卡那牌(Minor Arcana)解读" },
  { id: "t22", name: "权杖一", en: "Ace of Wands", arcana: "minor", suit: "Wands", file: "w01.jpg",
    scene: "一只巨大的手从云层中伸出，紧握一根粗壮的木杖，杖顶冒出嫩绿的新芽。远处有一座小城堡和起伏的山。",
    up: "那只手不是人的手，是从\"天上\"递下来的。你会感到一种被赠予的震动——某个念头、冲动、欲望，像种子一样突然落到你掌心。杖上的芽那么小、那么嫩，它已经破木而出。整张画面没有人在犹豫，没有人在思考，只有\"接住\"这个动作。正位时，这张牌说的是：一个原始的生命冲动已经交到你手里了，它还没成形，但它是活的。 背景那座遥远的城堡，是你将来可能抵达的地方，但现在还只是地平线上一个模糊的轮廓。",
    rev: "把画面倒过来看，那只手在下方，权杖朝下坠，新芽指向地面。直觉感受是——这颗种子被递出来了，但没有人接，或者接住了却倒着拿，芽朝下扎不进土里。 逆位时有一种\"时机错位\"的钝感：想法有了，但落不了地；热情起来了，但找不到出口。那根杖握在手里却像是握反了，力量是有的，方向却拧了。" },
  { id: "t23", name: "权杖二", en: "Two of Wands", arcana: "minor", suit: "Wands", file: "w02.jpg",
    scene: "一个穿红袍的男人站在城垛上，一手握着杵在墙上的权杖，另一只手托着一个地球仪。他望向远方的海与山。",
    up: "最强烈的感受是站在城墙边界上的那种安静。他已经在城墙内拥有了什么，但他没有看脚下，他在看外面。地球仪在他掌心里，世界是\"可以被握住的\"，但还没有被走出去。正位时这张牌不是行动，是行动前最后一口深呼吸。你手里已经有了资源和计划，你正在心里丈量\"我到底要不要迈出去\"。那个眺望的姿态里有一种克制的野心，不是冲动，是盘算。",
    rev: "倒过来，地球仪在下方，像是要从手中滑落。那个人的目光不再投向远方，而是被拽回脚下。直觉感受是犹豫变成了困住。你站在城墙上，但城墙不再是瞭望台，变成了围栏。逆位时有一种\"我其实可以走，但我告诉自己还不行\"的自欺。地球仪太重了，你托不住了，于是你假装自己还没准备好。" },
  { id: "t24", name: "权杖三", en: "Three of Wands", arcana: "minor", suit: "Wands", file: "w03.jpg",
    scene: "一个背影，站在高处，一手扶着一根权杖，另外两根插在身旁。他面前是大海，海上有船正在驶向远方。",
    up: "这张牌最在意的是那个背影。他不再看手里的东西了，他在看船，船已经出发了。正位的感受是一种已经做了第一步之后的等待与确信——你已经把东西投出去了，现在你只能站在岸上看它走远。三根杖很稳，他的站姿很定，没有焦虑。这是一种\"我做了我能做的，接下来看世界怎么回应\"的开阔。",
    rev: "倒过来，海在上方，船在头顶航行，人像是被压在水面之下。直觉上有一种目送落空的酸楚——船走了，但没有去你想让它去的方向；或者船根本没来。逆位的权杖三，那个背影不再是笃定的，而是等得太久，开始怀疑自己是不是站错了山头。你投出去的东西没有回响，你开始回头看那三根杖，想把它们拔起来换个地方。" },
  { id: "t25", name: "权杖四", en: "Four of Wands", arcana: "minor", suit: "Wands", file: "w04.jpg",
    scene: "四根高大的权杖插在地上，顶端挂着花环和果实。两个小人举着花束在杖下欢庆，远处是一座城堡。天空是明亮的黄色。",
    up: "满眼的庆典感。四根杖像门框，又像帐篷的四角，撑起了一个\"可以停下来\"的空间。正位时这张牌的画面直觉就是：你可以到了，你可以进来了，你可以放下了。 那个花环是圆形的，没有缺口，是一种\"成了\"的完整。远处城堡是安全的，近处有人在笑。这不是什么宏大的胜利，是那种\"终于把房子布置好了，可以请朋友来坐坐\"的踏实喜悦。",
    rev: "倒过来，花环垂落，果实朝下坠。那四根杖还在，但那个\"门\"的感觉变了——你站在门口，但觉得自己不属于里面。 逆位的权杖四有一种微妙的排斥感：庆典在进行，但你觉得自己是局外人；或者那个你以为可以安顿的地方，走进去之后发现没有你的位置。不是没有屋顶，是屋顶下没有归属感。" },
  { id: "t26", name: "权杖五", en: "Five of Wands", arcana: "minor", suit: "Wands", file: "w05.jpg",
    scene: "五个人各持一根权杖，混作一团，没有阵营，没有规则，像是在乱打，又像是在比划。背景是空旷的荒野。",
    up: "第一感受是吵。不是真正的战争，是那种一群人同时说话、谁也不让谁的混乱。五根杖交叉在一起，没有一个方向是一致的。正位时这张牌说的不是伤害，是摩擦。每个人都在表达，每个人都在争，但没有人真的想杀死谁。这是一种\"还没找到秩序\"的状态——团队里各说各话，脑子里各种念头打架，你被夹在中间，不是被攻击，是被噪音淹没。",
    rev: "倒过来，那些杖散开了，人往不同方向倒。直觉感受是打不动了，也不想打了。逆位的权杖五不是冲突升级，是冲突的能量泄了。可能是你终于不想争了，也可能是争到一半发现根本不值得。那种\"算了\"的疲惫感很强。但反面是——该争的也没争出来，问题还在那里，只是大家假装看不见了。" },
  { id: "t27", name: "权杖六", en: "Six of Wands", arcana: "minor", suit: "Wands", file: "w06.jpg",
    scene: "一个年轻人骑在白马上，头戴桂冠，手持挂着花环的权杖。两侧有人群举着权杖欢呼。他微微低头，像是在接受，又像是在害羞。",
    up: "最直觉的感受是被看见。白马、花环、人群的目光，全部汇聚在他身上。正位的权杖六不是\"你赢了\"，是\"你被认出来了\"。那种感觉是：你做的事情终于有人注意到了，有人在路边为你鼓掌。但他微微低头的姿态很关键——他不是趾高气扬的，他有一种受之有愧的微微不安。正位时这张牌提醒你：接受赞美，不必觉得自己不配。",
    rev: "倒过来，马在上方，人像是从马上滑落。花环松了。直觉感受是掌声落空，或者更微妙——你得到了认可，但那个认可不是给真正的你的。 逆位的权杖六有一种虚名的空洞感：别人在夸你，但你知道他们夸的那个形象不是你。或者，你渴望被看见，但周围没有人抬头。那种站在人群中间却被无视的孤独。" },
  { id: "t28", name: "权杖七", en: "Seven of Wands", arcana: "minor", suit: "Wands", file: "w07.jpg",
    scene: "一个人站在山丘顶端，双手紧握一根权杖，身体前倾，正在用力向下戳。山下有六根权杖朝他伸上来，像是六个人在挑战他。",
    up: "最强烈的画面感是一夫当关。他站在高处，这是他的优势，但他并不轻松——他的身体是前倾的、用力的，眉头是皱着的。正位的权杖七不是\"稳赢\"，是你正在被消耗，但你没有退。六根杖从下面涌上来，可能是六个人、六件事、六个质疑，你一个人扛。画面里没有援军。正位时这张牌说的是：你守得住，但你很累，而且你必须承认你累。",
    rev: "倒过来，他站在下方，六根杖从上方压下来。直觉感受是守不住了。不是被打败，是那种\"我突然不想守了\"的泄气。逆位的权杖七有一种\"我为什么要在这里挡着\"的质疑——你开始怀疑这个位置是不是值得守，这个立场是不是真的是你的。也可能是：你让出了位置，不是因为输了，是因为不值得。" },
  { id: "t29", name: "权杖八", en: "Eight of Wands", arcana: "minor", suit: "Wands", file: "w08.jpg",
    scene: "没有人。八根权杖在天空中斜飞，像是被同一股力量掷出，带着速度线。下方是开阔的田野和一条河流。",
    up: "这张牌没有人。没有投掷者，没有接收者，只有八根杖在飞。正位的直觉感受是事情自己动起来了。你不需要推，不需要拉，它们在飞。那种速度感是真实的——风在耳边，地面在后退。正位的权杖八是\"突然一切都快了\"：消息突然来了，进展突然有了，你之前等的所有东西一起到了。但画面里也有一层隐忧：没有人在控制方向。杖在飞，但谁也不知道它们会落在哪。",
    rev: "倒过来，杖朝下坠，像是要插进地里。直觉感受是急刹车。所有的速度突然被截断，消息卡在半路，计划停在半空。逆位的权杖八有一种\"明明已经在飞了，却被拽回来\"的挫败。也可能是太快了——快到你看清了，快到你想喊停但停不下来，于是画面翻转，用坠落来强制减速。" },
  { id: "t30", name: "权杖九", en: "Nine of Wands", arcana: "minor", suit: "Wands", file: "w09.jpg",
    scene: "一个男人，头上缠着绷带，微微佝偻，双手紧握一根权杖，像是在撑着不倒。他身后整齐地插着八根权杖，像一道栅栏。他看着前方，眼神疲惫但清醒。",
    up: "这张牌最让人在意的是那根绷带。他受伤了，而且伤在头上——是思想上的伤，是信念被打击过。但他还站着。八根杖在他身后，说明他已经经历了很多轮了，这是第九轮。正位的权杖九不是英雄，是老兵。他的姿态不是进攻，是\"我还能撑一下\"。正位时这张牌说的是：你已经很累了，你身上有伤，但你没有倒下，而且你不需要假装不疼。",
    rev: "倒过来，那根绷带松了，身后的八根杖像是要倒。直觉感受是最后一口气泄了。不是被打倒的，是自己撑不住了。逆位的权杖九有一种\"我真的不想再守了\"的放弃感。但注意，这个放弃不一定是坏事——也许是那道绷带早就该拆了，那些杖早就该放下了。逆位也可能是：你守的那个东西，其实早就空了，你只是在守一个习惯。" },
  { id: "t31", name: "权杖十", en: "Ten of Wands", arcana: "minor", suit: "Wands", file: "w10.jpg",
    scene: "一个人抱着十根粗重的权杖，弯着腰，低着头，脸完全被权杖挡住。他正走向远处一个小小的城镇。天空是灰暗的。",
    up: "最直观的感受是看不见脸。十根杖把他的整个正面都遮住了。他不是在走路，是在被东西推着走。正位的权杖十，那种重不是\"我可以承受\"的重，是\"我已经不知道我为什么在扛这些了\"的重。远处的小镇是目的地，但那么远、那么小。正位时这张牌说的是：你扛得太多了，而且你扛的方式让你看不见前方的路。 你的脸被挡住了，你不知道自己在走向哪里，你只知道不能停。",
    rev: "倒过来，杖要散了，人像是被压垮跪下去。直觉感受是终于掉了。十根杖抱不住了，哗啦散一地。逆位的权杖十有两种走向：一种是崩溃——你真的撑不住了，东西全掉了，你趴在地上；另一种是主动放下——你终于松手了，杖落地的声音很响，但你的腰直起来了。逆位的核心感受是：不管以哪种方式，这个重，必须卸下来了。" },
  { id: "t32", name: "权杖侍从", en: "Page of Wands", arcana: "minor", suit: "Wands", file: "wpag.jpg",
    scene: "一个年轻人站在旷野中，双手捧着一根权杖，杖顶有芽。他微微侧身，像是在端详这根杖，又像是在犹豫要不要走。背景有山。",
    up: "最打动人的是他看杖的那个眼神。不是握着，是捧着；不是出征，是端详。正位的权杖侍从是一种刚刚拿到新玩具的孩子气。他不确定这根杖能做什么，但他觉得它很酷。正位时这张牌说的是：你有一个新想法、新冲动，别急着用它，先看着它，先跟它玩。",
    rev: "倒过来，杖的芽朝下，年轻人像是被杖拽着走。直觉感受是三分钟热度。那个端详的眼神没了，变成了\"算了，这个不好玩\"的丢弃。逆位的权杖侍从是热情来得快去得也快：你昨天还兴奋得不行，今天就觉得没意思了。也可能是：你有一个想做的事，但你一直在\"准备\"，一直在\"看看\"，就是不出发。" },
  { id: "t33", name: "权杖骑士", en: "Knight of Wands", arcana: "minor", suit: "Wands", file: "wkni.jpg",
    scene: "一个骑士骑在一匹后腿跃起的骏马上，手持权杖，身体前倾。背景是沙漠，远处有金字塔形的山。马是动态的，像是随时要冲出去。",
    up: "整张画面只有一个字：冲。马在跃，人在倾，杖在指前方。没有犹豫，没有回头看。正位的权杖骑士是那种\"管他呢先跑了再说\"的能量。沙漠是荒的、没有路的，但他不在乎，他不需要路，他自己就是方向。正位时这张牌说的是：现在不是做计划的时候，是跑的时候。 你的身体比脑子先动了，那就让它动。但画面里也有一层隐忧——沙漠里没有水，你冲得很快，但你没带补给。",
    rev: "倒过来，马像是失蹄了，骑士往后仰。直觉感受是冲过头了，或者冲到一半马停了。逆位的权杖骑士有两种：一种是冲得太猛，摔了——你的热情烧得太快，把自己烧空了；另一种是突然不想冲了，马在原地打转，你拽着缰绳不知道往哪走。沙漠还是那片沙漠，但你没有了方向。逆位的核心感受是：你的冲劲被截断了，要么是被外力，要么是你自己突然怕了。" },
  { id: "t34", name: "权杖王后", en: "Queen of Wands", arcana: "minor", suit: "Wands", file: "wque.jpg",
    scene: "一位王后坐在宝座上，一手持一束向日葵，一手持权杖。宝座上有黑猫。她目光平视前方，嘴角有一丝笑意。",
    up: "最强烈的感受是她不需要站起来。她坐在那里，但你能感觉到她随时可以动。向日葵和权杖，黑猫趴在脚边——一个是热烈的、向外的；一个是安静的、本能的。正位的权杖王后是两种力量同时在她身上：她能热烈地表达，也能安静地观察。她不需要证明什么，她坐在那里就是中心。正位时这张牌说的是：你的魅力不需要表演，你的力量不需要展示。你就坐在那里，你的存在本身就是光和火。",
    rev: "倒过来，向日葵垂了，黑猫弓起了背。直觉感受是那股坐着的笃定感没了。逆位的权杖王后，她的笑变得有点僵，她的目光不再平视，而是开始看别人怎么看她。她开始需要反馈、需要掌声、需要确认\"我是不是还够好\"。也可能是另一种：火变成了灼烧。她的热情不再是温暖的，是控制性的——你必须按我的方式来，否则我的向日葵就不朝着你开了。" },
  { id: "t35", name: "权杖国王", en: "King of Wands", arcana: "minor", suit: "Wands", file: "wkin.jpg",
    scene: "一位国王坐在宝座上，手持权杖，权杖顶端有芽。宝座上有狮子和蜥蜴图案，他穿着饰有火蜥蜴图案的长袍。他的姿态是向前的，一只手握着杖，一只手搭在膝盖上，像是随时要站起来。",
    up: "和权杖王后不同，国王是随时要站起来的。他坐着，但他的身体重心是朝前的。火蜥蜴在西方传说中是能在火中生存的生物——正位的权杖国王是在火里待过的人，而且他不怕火。他的权威不是坐在王座上不动，是\"我可以随时走进去，也可以随时走出来\"。正位时这张牌说的是：你对自己的火是有掌控力的。你知道什么时候该烧，什么时候该收。你不是被热情驱动的，你是驾驶热情的人。你是有远见的领导者，用行动力和热情带动众人。",
    rev: "倒过来，火蜥蜴的图案朝下，权杖的芽指向地面。直觉感受是那个\"随时可以站起来\"的姿态变成了\"坐不住了\"。逆位的权杖国王，他的前倾不再是蓄势，是焦躁。他需要控制一切，需要所有火都按他的意志烧。或者反过来——他的火灭了。他坐在那里，但心里没有热度了，他只是在扮演一个\"应该有热情\"的角色，专横且缺乏耐心。 圣杯属水，全是关于\"盛\"与\"溢\"、\"给\"与\"收\"、\"看进去\"与\"流出来\"的事。" },
  { id: "t36", name: "圣杯一", en: "Ace of Cups", arcana: "minor", suit: "Cups", file: "c01.jpg",
    scene: "一只巨大的手从云中伸出，托起一只金色圣杯。杯中水满了，五道水流向下倾泻，落入下方一片睡莲池塘。一只白鸽衔着十字圣饼从上方飞降。",
    up: "那只杯不是被倒满的，是自己满出来的。五道水流不是泼出去的，是溢出来的。正位的第一感受是：你的心开了，而且开得太彻底了。 那只手不是人的手，是从云里伸出来的，说明这个\"满\"不是你挣来的，是给的。鸽子在飞下来，不是飞走——有什么东西正在降临到你里面。睡莲在下面安静地等着接水。正位时这张牌说的是：你正被一种巨大的温柔充满，你不需要做任何事，你只需要像那只杯一样，敞开，然后满。",
    rev: "倒过来，杯口朝下，水全洒了。那只手还举着，但杯是空的。直觉感受是你敞开了，但没有东西流进来；或者流进来了，你接不住。 逆位的圣杯一有一种\"心口那里是空的\"的钝痛。你想爱，你想感受，但那个杯底好像有个洞，什么倒进去都留不住。鸽子在画面上方，但它衔着的东西没有落下来——恩典悬在半空，够不着你。也可能是：你拒绝被倒满，你把杯扣过来了，你说\"我不需要\"。" },
  { id: "t37", name: "圣杯二", en: "Two of Cups", arcana: "minor", suit: "Cups", file: "c02.jpg",
    scene: "一男一女面对面站着，各举一只杯，像是在交杯。他们之间上方有一根双蛇缠绕的带翼权杖（商神杖），杖顶有一个狮头。两人目光对视，神情安静。背景是平静的田野。",
    up: "最打动人的是对视。不是拥抱，不是亲吻，就是看着。两只杯举到一样的高度，不多不少。正位的圣杯二说的不是\"我对你有感觉\"，是\"我看见你了，你也看见我了\"。那个双蛇杖在两人之间，蛇是交缠的但又是平衡的——两种力量缠绕在一起，但谁也没有压过谁。狮头在最上方，是见证者。正位时这张牌说的是：此刻你面前有一个人（或一段关系），你们是平的。没有谁高谁低，没有谁在追谁在逃。就是两只杯碰在一起，叮的一声。",
    rev: "倒过来，两只杯不再对等。那个对视的角度变了——变成了一个人仰视、一个人俯视。直觉感受是失衡。你在这段关系里，要么给得太多，要么收得太多。那根双蛇杖也倒了，缠绕变成了纠缠。逆位的圣杯二不是\"不爱了\"，是\"还在，但不对等了\"。你举着杯，但对面那个人没有举起来，或者举得太高你够不着。那种\"我伸出手，你不在那个高度\"的落空。" },
  { id: "t38", name: "圣杯三", en: "Three of Cups", arcana: "minor", suit: "Cups", file: "c03.jpg",
    scene: "三个女子穿着鲜艳的裙子，在田野中围成一圈跳舞，各自高举一只杯。她们脚下有南瓜、葡萄和瓜果。天空明亮，草地是绿色的。",
    up: "第一感受是热闹，而且是那种不需要理由的热闹。三个人不是在庆祝什么具体的事，她们就是在那里，就是在一起，就是在跳。杯举得很高，高过头顶——不是在喝，是在向天空示意。地上的瓜果是熟的、多的、快裂开的。正位的圣杯三说的是：你此刻被一种\"我们在一起\"的快乐包围着。不是深刻的、不是沉重的，是那种\"管他呢先干了这杯\"的轻盈。你不需要一个人扛，你身边有人，她们在跳，你也在跳。",
    rev: "倒过来，三只杯向下倾，酒要洒了。三个人的舞步乱了。直觉感受是热闹是假的，或者热闹过了头。逆位的圣杯三有两种：一种是\"我在这群人中间，但我不属于这里\"——你在笑，但你的眼睛没有在笑；另一种是太多、太满、太吵了，你被社交淹没了，你开始想念一个人安静待着的感觉。地上的瓜果倒过来，是熟透了烂掉的意思——快乐如果不被珍惜，它就只是消耗。" },
  { id: "t39", name: "圣杯四", en: "Four of Cups", arcana: "minor", suit: "Cups", file: "c04.jpg",
    scene: "一个年轻人坐在一棵树下，双臂交叉抱在胸前，目光低垂，看着面前地上的三只杯。第四只杯正从云中伸出的手递过来，但他没有抬头看。他的表情是倦怠的、不满意的。",
    up: "最刺痛的画面是那只手在递，但他不看。三只杯就在面前，他也不看。他的眼睛是半闭的，嘴角是向下的。正位的圣杯四不是悲伤，是腻。是\"我拥有了一些东西，但它们不能让我满足了\"的那种倦怠。那只云中的手是新的可能、新的情感、新的邀请，但它来了，他懒得伸手。正位时这张牌说的是：你被一种\"什么都提不起兴趣\"的灰雾罩住了。不是没有东西给你，是你不想接。你抱着自己的不满足，像抱着一个旧习惯，不肯松手。",
    rev: "倒过来，那个人的目光终于动了。也许是抬头了，也许是伸手了。直觉感受是那层壳裂了一条缝。逆位的圣杯四不是突然狂喜，是\"我好像……可以看看那只杯里是什么\"。你从那种\"什么都不要\"的麻木里，微微探出了一根手指。也可能是另一种：你终于意识到你一直在拒绝，你看见自己交叉的双臂有多紧，你开始觉得累了，想松开。逆位的核心是：那扇你一直假装看不见的门，你终于承认它在那里了。" },
  { id: "t40", name: "圣杯五", en: "Five of Cups", arcana: "minor", suit: "Cups", file: "c05.jpg",
    scene: "一个穿黑色斗篷的人低着头，弓着背，看着地上三只翻倒的杯子，酒液流了一地。在他身后，还有两只杯子稳稳地立着。远处有一座桥和一座城堡。天空是灰暗的。",
    up: "最让人心碎的是他只看那三只倒了的杯。他的整个身体——低下的头、弓起的背、黑色斗篷——全部朝向那三滩酒液。身后那两只立着的杯子，他看不见。不是不存在，是他的眼睛不肯转过去。正位的圣杯五说的不是\"失去\"，是\"我选择只看见失去\"。你心里有两只杯是满的，但你全部的注意力都浇在了那三只空了的上面。桥在远处，可以走，但你不想走。你就想站在这里，看着酒流干。",
    rev: "倒过来，三只倒着的杯在上方，两只立着的杯在下方。那个人的头微微抬了一点。直觉感受是你终于开始转身了。不是不疼了，是疼够了。你看着那三滩酒，看了很久，终于觉得冷了，终于想回头看看身后还有什么。逆位的圣杯五不是\"释然\"，是\"我允许自己不再只盯着那三滩酒了\"。你的斗篷还是黑的，你的背还是弯的，但你的脚尖转了一个方向。那个桥，你终于看见了。" },
  { id: "t41", name: "圣杯六", en: "Six of Cups", arcana: "minor", suit: "Cups", file: "c06.jpg",
    scene: "一个小男孩捧着一只装满花的杯子，递给一个小女孩。他们站在一座老房子的花园里，石阶上摆着好几只插满花的杯子。一个持戟的卫兵正从画面边缘走远。光线是柔和的、金色的。",
    up: "最强烈的感受是小。一切都是小的——小孩子、小杯子、小花园。正位的圣杯六不是\"回忆\"这个词能概括的，它是一种\"回到那个还不需要懂事的下午\"的感觉。男孩递花给女孩，没有目的，没有意义，就是\"给你\"。石阶上那些杯子都满了，花都快溢出来了，但没有人觉得多，没有人觉得该省着。正位时这张牌说的是：你心里有一个地方，那里的人不需要你证明什么，不需要你成为什么，你只需要接住那朵花，说谢谢。那个走远的卫兵是\"成人世界的规则正在退场\"。",
    rev: "倒过来，花从杯子里垂下来，两个孩子的距离远了。直觉感受是你回不去了，或者你不想回去了。逆位的圣杯六有两种：一种是\"我困在过去里了\"，你一直在回头看那个花园，觉得现在的一切都不如那时候，你拒绝长大；另一种是\"那个花园的门关了\"，你试图回去，但那个卫兵不让你进了。你长大了，你进不去了。那种\"我再也收不到那样单纯的一朵花了\"的酸。" },
  { id: "t42", name: "圣杯七", en: "Seven of Cups", arcana: "minor", suit: "Cups", file: "c07.jpg",
    scene: "一个人站在画面下方，面前漂浮着七只杯子，排列在云层中。每只杯里装着不同的东西：珠宝、桂冠、城堡、龙蛇、布中人影、人头、花环。那个人背对观者，双手微张，像是在选，又像是在发呆。",
    up: "最强烈的感受是眼花。七只杯，七种东西，全在云上飘着，没有一只是落在地上的。那个人站在那里，手伸着，但哪只都没碰。正位的圣杯七不是\"选择多\"这么简单，是\"全都是幻的，但你分不清哪只是真的\"。珠宝在发光，但它在云上；城堡很宏伟，但你走不进去；龙蛇在杯子里盘着，你不知道它会不会咬你。正位时这张牌说的是：你面前有很多可能、很多幻想、很多\"如果我……就好了\"，但它们全在云里。你伸手去够，手会穿过云。你需要低头看自己的脚，踩在地上，然后只选一只。",
    rev: "倒过来，七只杯往下坠，云散了。直觉感受是幻象碎了。那些杯子不再飘着了，它们开始落，有的碎了，有的露出里面是空的。逆位的圣杯七有两种：一种是痛苦的清醒——你终于看见那些你追了很久的东西里面什么都没有，那个城堡是纸糊的，那个桂冠是塑料的；另一种是释然的清醒——\"好吧，那我不选了，我走我自己的路。\"逆位的核心是：云散了，你终于踩在地上了。也许地上什么都没有，但至少是实的。" },
  { id: "t43", name: "圣杯八", en: "Eight of Cups", arcana: "minor", suit: "Cups", file: "c08.jpg",
    scene: "一个穿红斗篷的人拄着手杖，正背对八只整齐叠放的杯子，走向远处的群山。月亮是残月。地面是湿的，有水流。八只杯被留在身后，完好无损。",
    up: "那八只杯是完好的，没有倒，没有碎，没有空。它们好好地叠在那里。但那个人走了。正位的圣杯八说的不是\"失去了所以离开\"，是\"还在，但我不想要了\"。这是比失去更难的离开——你走的时候，那些东西还是好的，别人会觉得你疯了，\"明明都好好的你走什么\"。但你心里知道，够了，满了，但不是我想要的那种满。残月在头顶，路是湿的、暗的，远处的山很高。正位时这张牌说的是：你正在走向一个\"更少但更真\"的地方，代价是放下那些\"明明还不错\"的东西。",
    rev: "倒过来，那个人像是走到一半又转回来了。直觉感受是走不动了，或者舍不得。逆位的圣杯八不是\"你回去了\"，是\"你的脚在走，心在回头看\"。你离开了一段关系、一个地方、一种生活，但你每走一步都在想\"也许我应该回去\"。那八只杯在身后叫你，你听见了。逆位的核心感受是：你还没有真正走。你的身体在走，但你心里还在那八只杯旁边坐着。 或者另一种：你根本不敢走，你站在原地，看着山，告诉自己\"明天再走\"，而明天永远不会来。" },
  { id: "t44", name: "圣杯九", en: "Nine of Cups", arcana: "minor", suit: "Cups", file: "c09.jpg",
    scene: "一个胖胖的男人坐在长凳上，双臂交叉，嘴角上翘，带着一种\"我很满意\"的表情。他身后，九只杯子整整齐齐地摆在一块蓝色桌布上。他穿着华丽的衣服，帽子是红色的。",
    up: "那个笑，不是大笑，是那种\"嗯，不错\"的、自满的、微微向后仰的笑。他交叉着手臂，是一种\"我得到了，而且我不需要再伸手去拿了\"的姿态。正位的圣杯九是\"心愿达成之后的那口满足的叹息\"。九只杯在后面，一只不多一只不少，刚刚好。你不需要第十只。正位时这张牌说的是：你可以满意了。你不用谦虚，不用\"但是还有……\"，你可以就坐在这里，交叉着手臂，对自己说\"够了，很好了\"。允许自己满足，是一种能力。",
    rev: "倒过来，那个笑僵了。手臂交叉不再是满足，是防御。直觉感受是你告诉自己\"我满足了\"，但你不信。逆位的圣杯九有两种：一种是\"我得到了我想要的，但它没有让我快乐\"——你坐在那九只杯前面，但心里是空的；另一种是贪婪——九只杯不够了，你要第十只、第十一只，你的手臂交叉是因为你怕别人来拿你的。那个笑不再是满足的，是\"你们看看我有多少\"的炫耀。逆位的核心是：你的满足是假的，或者你的满足是有条件的、恐惧的。" },
  { id: "t45", name: "圣杯十", en: "Ten of Cups", arcana: "minor", suit: "Cups", file: "c10.jpg",
    scene: "一对夫妻并肩站立，双手举向天空，天空中有一道彩虹，彩虹上排列着十只杯子。他们身旁，两个小孩手拉手在跳舞。远处有一座小屋和绿色的田野。阳光普照。",
    up: "两个人举着手，但不是在祈祷，是在指着彩虹。\"你看，你看那个。\"两个小孩在跳，不是因为被要求跳，是因为开心。十只杯在天上，不在手里——它们不是被握住的，是被看见的。正位的圣杯十不是\"完美家庭\"这么窄，是\"你站在一个地方，身边有你爱的人，天上有光，你不需要更多了\"。那种圆满不是拥有十只杯，是你抬头，彩虹就在那里，你不需要把它摘下来。正位时这张牌说的是：你正在经历一种\"够了\"的幸福。别分析它，别怀疑它，就站在这里，举着手，看。",
    rev: "倒过来，彩虹在下方，杯子要掉了。那对夫妻的手放下来了。直觉感受是那道光暗了，或者你不再相信那道光了。逆位的圣杯十不是\"家庭破裂\"这么粗暴，是更微妙的东西：\"我们站在一起，但我们不再一起抬头看了。\"你和你爱的人之间，那个\"你看那个\"的默契没了。两个孩子还在跳，但大人不看了。逆位的核心是：那个圆满还在，但你不再相信它是真的了。 你开始想\"这不会是永远的吧\"，于是你把手放下了。你一旦放下手，彩虹就真的远了。" },
  { id: "t46", name: "圣杯侍从", en: "Page of Cups", arcana: "minor", suit: "Cups", file: "cpag.jpg",
    scene: "一个年轻人站在小溪边，双手捧起一只杯子，杯口探出一条小鱼，正看着年轻人。年轻人的表情是惊喜的、微微张着嘴的。背景是波浪形的天空和水面。",
    up: "那条鱼，它不在水里，它在杯子里，它探出头来看你。正位的圣杯侍从是一种\"你的感受里冒出了一个小小的、活的东西\"的感觉。你没有预料到它，你只是捧着杯在看，突然它探出头来了。那个惊喜的表情是真的——不是夸张的惊喜，是\"啊，你在啊\"的那种轻轻的、眼睛亮了一下的惊喜。正位时这张牌说的是：你心里有一个新的感受、新的柔软、新的创意正在探头。它很小，它只是一条鱼，但它是活的。你别吓它，你捧着就好。",
    rev: "倒过来，鱼要从杯子里掉出来了，水在洒。直觉感受是那个小小的感受被你吓跑了，或者你不敢看它。逆位的圣杯侍从有两种：一种是\"我感受到了什么，但我告诉自己那不算什么\"——你看见那条鱼了，但你把杯扣上了，你假装没看见；另一种是情感上的幼稚——你捧着杯在等，等一条鱼跳出来，等一个感受来填满你，你不去找，你就站在那里等，而且你等得不耐烦了。那个张着的嘴不再是惊喜，是\"怎么还没有\"的抱怨。" },
  { id: "t47", name: "圣杯骑士", en: "Knight of Cups", arcana: "minor", suit: "Cups", file: "ckni.jpg",
    scene: "一个骑士骑着一匹白马，马在缓步走着，没有奔跑。骑士一手持缰，一手向前平举一只杯，像是在递出去。他穿着饰有波浪图案的衣服。背景是一条平静的小河和起伏的丘陵。",
    up: "和权杖骑士完全不同，这匹马没有在跑。它是走的，是缓的。那只杯不是举过头顶，是平举着，递向你。正位的圣杯骑士最核心的感受是：有人在慢慢走向你，手里捧着一样柔软的东西，他不急，他在等你伸手接。 整个画面是安静的、流动的、没有攻击性的。波浪在他的衣服上，说明他本身就是水做的——他的情感不是武器，是他整个人。正位时这张牌说的是：有一个邀请正在慢慢靠近你，可能是爱，可能是灵感，可能是一个温柔的提议。它不催你，但你得伸手。",
    rev: "倒过来，那只杯倾了，水在流走。马停了，或者在原地转。直觉感受是那个递杯子的动作收回去了，或者递出去了但没人接。逆位的圣杯骑士有两种：一种是\"我捧着我的心走向你，但你不接\"——那只杯举在半空，举得太久了，手臂酸了，水洒了；另一种是虚假的深情——他举着杯，但杯是空的，那个\"递给你\"的姿态是表演。马不走，是因为他根本不想去任何地方，他只是喜欢\"正在递出\"这个姿势。逆位的核心是：那个温柔是真的吗？还是只是看起来像温柔？" },
  { id: "t48", name: "圣杯王后", en: "Queen of Cups", arcana: "minor", suit: "Cups", file: "cque.jpg",
    scene: "一位王后坐在海边的一座宝座上，双手捧着一只极其精美的杯子，目光低垂，凝视着杯中。宝座上有贝壳、人鱼、天使的雕刻。她身后是大海，海面平静。她穿着蓝白色的衣服，头上戴着冠冕，但她的全部注意力都在那只杯上。",
    up: "她在看杯子里面，不是看海，不是看远方，是看手里这只杯。她的目光是向内的、深的、安静的。正位的圣杯王后说的是一种\"我不需要向外看，我的里面就是一片海\"的状态。她不需要别人来倒水，她不需要别人来告诉她感受是什么。她捧着杯，她知道里面有什么。海面在她身后是平的，说明她的情绪不是没有，是她能让它平。正位时这张牌说的是：你现在需要做的不是表达，不是倾诉，是安静地看进去。你手里有一只杯，里面有答案，但你得停下来，低下头，看。",
    rev: "倒过来，杯中的水要溢出来，或者她的目光散了。直觉感受是她看不进去了，或者看进去了但被淹了。逆位的圣杯王后有两种：一种是\"我的感受太多了，我捧不住了\"——那只杯满了，满到溢出来，你不知道该先处理哪一种情绪；另一种是共情过度——你一直在看杯子里面，但那不是你的杯，是别人的。你把所有人的情绪都倒进自己的杯里，然后你分不清哪个是你的了。逆位的核心是：你和你的感受之间，边界模糊了。 要么是你感受不到了，要么是你感受太多了，多到不是你的了。" },
  { id: "t49", name: "圣杯国王", en: "King of Cups", arcana: "minor", suit: "Cups", file: "ckin.jpg",
    scene: "一位国王坐在大海中央的宝座上，一手持杯，一手持权杖。他的表情是平静的、克制的。他穿着蓝金色的袍子，脖子上挂着鱼形吊坠。海面在他周围波动，但他的宝座是稳的。",
    up: "和圣杯王后不同，国王是坐在海面上的。王后在海边，他在海中间。水在他周围，但他不在水里。正位的圣杯国王最核心的感受是：他拥有所有的情绪，但他不被任何一只情绪卷走。 那只杯在他手里，是稳的，不洒。权杖在另一只手，是直的，不歪。他不是没有感受，他是感受过了，然后他选择不被它带走。正位时这张牌说的是：你正处在一个\"我感受到了所有，但我选择稳稳坐着\"的位置。你不需要否认你的情绪，你只是不需要成为你的情绪。你是坐在海上的那个人，海在动，你不动。",
    rev: "倒过来，海水漫上来了，宝座在晃。那只杯里的水在倾。直觉感受是那个\"我不动\"的平衡被打破了。逆位的圣杯国王有两种：一种是压抑——你坐得太稳了，稳到你自己都相信你没有感受了，但水在涨，你的宝座在晃，你快坐不住了。你必须让那只杯洒一次，否则你会连人带座被翻进海里；另一种是用情感控制——你不是在感受，你是在用你的感受压别人。\"我为你付出了这么多\"变成了武器，那只杯不再是捧着的，是扣在别人头上的。逆位的核心是：你的水，要么堵住了，要么变成了洪水。你失去了那个\"海在动，我不动\"的中心。 圣杯始终是一个问题：你的那只杯，是满的还是空的？你是在往里看，还是在看别人手里的？你是在递出去，还是在收回来？ 水没有对错，它只是流。你站在哪里，它就从哪里经过你。 宝剑属风，属头脑，属\"想\"。但看完整副牌你会发现，这些画里最疼的从来不是\"想错了\"，而是想得太清楚了。剑是冷的，但画面里的人都是热的。" },
  { id: "t50", name: "宝剑一", en: "Ace of Swords", arcana: "minor", suit: "Swords", file: "s01.jpg",
    scene: "一只灰色的手从云层中伸出，握着一把双刃剑，剑尖直指天空。剑身上穿过头顶一顶金色王冠，王冠两侧垂下橄榄枝和月桂枝。背景是灰白色的天空和远处的山尖。",
    up: "那把剑是直的。不是斜的，不是弯的，是笔直朝上的。正位的第一感受不是\"胜利\"，是\"一刀切下去了\"。你心里有一团乱麻，突然有一刻，你听见\"嚓\"的一声，不是你把麻解开了，是你不找了，你切了。那顶王冠被剑穿过去，但没有碎——说明这个\"切\"不是毁灭，是穿透。你穿过了那个你一直不敢碰的真相，你从另一边出来了。橄榄枝和月桂挂在两侧，是切完之后的安静。正位时这张牌说的是：你终于想清楚了。不是慢慢想清楚的，是一瞬间，像剑一样，直上直下，没有余地。",
    rev: "倒过来，剑尖朝下，像是要从云里坠落。那只手还握着，但握得紧了，指节发白。直觉感受是你切偏了，或者你切了不该切的东西。逆位的宝剑一有一种\"我想明白了，但那个明白是错的\"的恐惧。你用一个很锋利的念头斩断了什么，但事后你发现那个结本来可以慢慢解开的。那顶王冠在剑尖下方晃着，快要掉了。逆位也可能是：你不敢切。 剑举在云里，你握着，但你不敢往下落。你知道该想清楚什么，但你害怕那个清楚。你宁愿继续雾着。" },
  { id: "t51", name: "宝剑二", en: "Two of Swords", arcana: "minor", suit: "Swords", file: "s02.jpg",
    scene: "一个女人坐在石凳上，双眼被布条蒙住，双手各持一把剑，交叉在胸前。她身后是大海，一轮新月挂在天空。她的姿态是静止的、僵硬的。水面平静，但你能感觉到风。",
    up: "两把剑交叉在胸前的角度，是举着，不是砍着，是抱着。像抱着一个十字架，又像抱着一个\"不\"。她看不见——布条是紧的、是实的。正位的宝剑二不是\"我在思考\"，是\"我拒绝看\"。两把剑一左一右，是两个选项、两种声音、两个人在说话，她全听见了，但她把眼睛蒙上了，把剑抱紧了，意思是\"我不选，我不动，我谁也不看\"。身后的海是平的，新月是弯的——世界在等她，但很安静，不催。正位时这张牌说的是：你正处在一个\"我宁可瞎着也不要做决定\"的状态。你不是看不见，你是不想看见。",
    rev: "倒过来，布条松了，剑要滑落。直觉感受是那个\"我不动\"撑不住了。逆位的宝剑二不是\"你终于选了\"，是\"你被迫看了\"。布条不是你自己摘的，是被风吹松的，是被别人扯掉的。你睁开眼的那一瞬间，两把剑不再交叉了，它们往两边倒，你手里什么都抓不住。逆位的核心是：你一直用来保护自己的那个\"不看\"，失效了。 你必须面对那个你逃避了很久的选择，而且你发现，你逃了这么久，选项已经变了，比你想象的更少了。" },
  { id: "t52", name: "宝剑三", en: "Three of Swords", arcana: "minor", suit: "Swords", file: "s03.jpg",
    scene: "一颗红色的心，被三把剑穿透。一把从上方直插，两把从两侧斜穿。背景是灰色的云，雨丝正在落下。没有手，没有人，只有心和剑和雨。",
    up: "最疼的不是剑，是那颗心的颜色。它是红的，是暖的，是活的。剑是灰的、冷的、直的。三把剑不是同时插进去的——你能感觉到一把先来了，然后第二把，然后第三把。正位的宝剑三没有人在哭，没有人在喊，画面是静的。但那个静比哭更疼。雨在下，不是暴雨，是那种\"天也在陪你淋\"的细密的、没完没了的雨。正位时这张牌说的是：你心里有一个地方，被三样东西同时扎着。你知道是哪三样，你不需要说出来。你不需要\"处理\"它，你现在只需要让它疼着。雨会下的。你不用撑伞。",
    rev: "倒过来，三把剑从心里滑出来，雨往上走。直觉感受是你在拔剑，但拔得很慢，而且每拔一下都带出一块肉。逆位的宝剑三不是\"不疼了\"，是\"我开始处理这个疼了，但处理本身也很疼\"。你试着把那些话、那些事、那些人从心里抽出来，但你发现它们已经和心长在一起了。你拔出来的不是剑，是你的一部分。逆位也可能是另一种：你把剑推得更深了，你告诉自己\"我不该这么疼\"，你压着，按着，假装那三把剑不存在。雨还在下，但你把窗帘拉上了。" },
  { id: "t53", name: "宝剑四", en: "Four of Swords", arcana: "minor", suit: "Swords", file: "s04.jpg",
    scene: "一个男人双手合十，躺在石棺般的平台上，像是在沉睡，又像是在祈祷。他的头顶上方悬挂着三把剑，第四把剑平放在他身下的石台上。背景是教堂般的彩色玻璃窗，上面有跪着的人像。光线是昏暗的、安静的。",
    up: "他躺着，不是坐着想，不是站着扛，是平躺。双手合十不是祈祷，是\"我把手放下了，我什么都不抓了\"。三把剑在头顶悬着，但它们是挂着的，不是落着的。正位的宝剑四说的不是\"危险过去了\"，是\"我选择现在不动了\"。那些剑还在那里，它们没有消失，但你闭上了眼睛，你把手合上了，你允许自己暂时不去管它们。那个彩色玻璃窗是另一个世界，是\"等你准备好了再回去\"的地方。正位时这张牌说的是：你现在不需要清醒，不需要想通，不需要解决。你需要躺下来，闭上眼睛，呼吸。那三把剑不会掉下来的，至少今天不会。",
    rev: "倒过来，那三把剑在下方，像是正在落向他。那个躺着的人像是被惊醒了，眼睛要睁开了。直觉感受是你还没休息够，但你被叫起来了。逆位的宝剑四有一种\"我明明还在恢复，但世界不允许我继续躺着\"的焦躁。你身体还在石棺上，但你心里已经坐起来了，你在想\"我是不是躺太久了\"\"我是不是该起来了\"。那第四把剑在身下，硌着你的背——你躺不安稳。逆位的核心是：你剥夺了自己的休息，或者你的休息被剥夺了。 你还没有准备好睁眼，但你强迫自己睁了。" },
  { id: "t54", name: "宝剑五", en: "Five of Swords", arcana: "minor", suit: "Swords", file: "s05.jpg",
    scene: "一个男人正面朝观者走来，嘴角带着一丝笑，怀里抱着三把剑。他身后，两个人正弯腰走远，其中一人低着头。地上散落着两把剑。天空是翻涌的灰云。",
    up: "那个笑，不是大笑，是嘴角微微上翘的、\"我赢了\"的笑。但他赢了什么？他怀里抱着三把剑，地上还有两把——五把剑他拿了三把，另外两个人各丢了一把。正位的宝剑五说的不是\"胜利\"，是\"你赢了，但你看看你赢的是什么\"。那两个人走远了，低着头，不是被打败了，是不想再跟你说了。你抱着三把剑，但它们很重，而且没有人陪你走。云是翻的，风是冷的。正位时这张牌说的是：你可能在一场争论、一场博弈里占了上风，但你回头看看——对面那个人不跟你玩了。你抱着你的\"对\"，站在原地，很冷。",
    rev: "倒过来，剑要散了，那个笑僵在脸上。直觉感受是你突然不想赢了，或者你发现赢了也没有用。逆位的宝剑五有两种：一种是\"我后悔了\"——你看着那两个人走远的背影，你突然想喊\"等等\"，但你喊不出口，因为你怀里抱着三把剑，你腾不出手；另一种是你终于把剑放下了——你意识到抱着它们毫无意义，你松开手，剑落在地上，声音很响，但你松了一口气。逆位的核心是：那个\"我必须赢\"的执念，正在松动。 也许你还是会赢，但你不再需要那个笑了。" },
  { id: "t55", name: "宝剑六", en: "Six of Swords", arcana: "minor", suit: "Swords", file: "s06.jpg",
    scene: "一个人撑着船篙，船上有六把剑竖立着插在船头。船上坐着一个蒙头的人和一个孩子。水面在船后方是波涛汹涌的，前方是平静的。远处是河岸。天空是灰蓝色的。",
    up: "水的变化，后面是浪，前面是平的。船正在从\"乱\"驶向\"不乱\"。那个蒙头的人不看后面，也不看前面，只是坐着。六把剑竖在船里，它们没有丢，它们跟着你一起走。正位的宝剑六不是\"伤痛过去了\"，是\"你带着伤在移动，而且你在往更安静的方向走\"。你没有把剑扔进海里，你带着它们上了船。它们重，但它们没有让你沉。那个孩子在你身边，是你心里还活着的那一小块柔软。正位时这张牌说的是：你正在离开一个很疼的地方。你没有好，你只是在走了。你不需要回头确认那个浪还在不在。你只需要坐着，让船往前。",
    rev: "倒过来，船像是停了，或者在原地打转。那些浪从前方涌来。直觉感受是你走不了了，或者你不想走了。逆位的宝剑六有两种：一种是\"我试着离开，但水流把我推回来了\"——你做了决定要远离那个人、那件事、那种状态，但你发现自己又回到了原来的位置上，船没有动；另一种是你拒绝上船——你站在那个波涛汹涌的岸边，看着船，你说\"我不走，我要在这里解决\"，但你解决不了，你只是站在浪里被拍。逆位的核心是：你还没有允许自己离开。你觉得离开是逃，是认输，是放弃。但那张画告诉你：船是往前走的，水会平的。" },
  { id: "t56", name: "宝剑七", en: "Seven of Swords", arcana: "minor", suit: "Swords", file: "s07.jpg",
    scene: "一个人偷偷摸摸地抱着五把剑，正从一片帐篷营地中溜走。他回头看了一眼，表情是紧张的、算计的。身后还有两把剑插在地上没有拿走。远处帐篷里有人影。天空是暗黄色的。",
    up: "他抱着五把剑，走得不快不慢，但他回头了。那个回头里有紧张、有得意、也有一丝\"我是不是拿太多了\"的心虚。正位的宝剑七不是简单的\"欺骗\"，是\"你从某个局面里拿走了一些不属于你的东西，或者你没有拿全部就走了\"。那两把留在地上的剑是\"你不敢拿的\"或者\"你良心发现留下的\"。正位时这张牌说的是：你正在用一种不正面的方式处理一件事。你在绕，你在偷，你在\"先拿了再说\"。你知道这不是最磊落的方式，但你告诉自己\"我别无选择\"。那个暗黄色的天空是\"这件事不会一直这么安静的\"。",
    rev: "倒过来，剑要掉了，那个人的脚步乱了。直觉感受是你被发现了，或者你发现了自己。逆位的宝剑七有两种：一种是\"你抱着五把剑走到一半，突然觉得太重了、太假了，你停下来了\"——你不想再这样了，你想把剑放回去，但你不知道怎么开口；另一种是你发现别人在对你做同样的事——你一直以为你在掌控局面，突然你发现你才是那个帐篷里被偷的人。逆位的核心是：那个\"偷偷摸摸\"维持不住了。你要么把剑还回去，要么你承认你拿了，要么你被抓住。 总之，你不能再回头看了。" },
  { id: "t57", name: "宝剑八", en: "Eight of Swords", arcana: "minor", suit: "Swords", file: "s08.jpg",
    scene: "一个女人被布条蒙住眼睛，全身被绳索绑住，站在一片泥地里。八把剑围在她周围，剑尖朝上，像一圈栅栏。远处是一座城堡，在灰暗的天空下。她的脚是湿的，裙子是红色的。",
    up: "最让人窒息的是那些剑并没有碰到她。它们插在地上，围着她，但没有一把刺进她的身体。绳子是绑着的，但你可以看到——如果她蹲下来、侧一下身，她是可以从剑与剑之间的缝隙走出来的。但她不动。正位的宝剑八最核心的感受是：困住你的不是那些剑，是那条蒙住你眼睛的布。你看不见，所以你相信\"我走不出去\"。八把剑是八个念头、八种恐惧、八个\"你不行\"的声音，它们围着你，但它们没有一把是真的刺进你了。正位时这张牌说的是：你觉得自己被困死了，但如果你能冷静下来，你会发现绳子没有你想象的紧，剑之间是有缝的。你不需要把剑拔出来，你只需要把布摘下来。",
    rev: "倒过来，剑在上方悬着，绳子松了。直觉感受是你开始动了。也许你摘了布条，也许你扭开了绳子，也许你只是终于不再站着一动不动了。逆位的宝剑八不是\"你自由了\"，是\"你开始相信你可以动了\"。你的脚还在泥里，你的裙子还是湿的，但你转了一下头，你感觉到了风从某个方向来——那个方向没有剑。逆位的核心是：那个\"我出不去\"的信念，正在碎裂。 你还没有完全走出去，但你已经不再相信\"我永远不会出去\"了。" },
  { id: "t58", name: "宝剑九", en: "Nine of Swords", arcana: "minor", suit: "Swords", file: "s09.jpg",
    scene: "一个人坐在床上，双手捂着脸，身体前倾，像是在哭，又像是在想。他身后的墙上，九把剑整整齐齐地横挂着。床上的被子是暗红色的，有玫瑰和星座的图案。窗外是黑的。",
    up: "最值得注意的是那九把剑在墙上。它们不在他身上。它们好好地、整整齐齐地挂在墙上。但它们在他身后，他看不见它们，他只知道它们在那里。正位的宝剑九说的不是\"九件事在伤害你\"，是\"你知道有九把剑在你身后，你不敢转身，所以你坐在这里，捂着脸，一夜一夜地想\"。那些剑可能根本不会掉下来，但你不知道它们会不会掉下来，这个\"不知道\"比掉下来本身更折磨你。窗外的黑是没有尽头的黑。正位时这张牌说的是：你正在经历一种\"凌晨三点坐起来想事情\"的折磨。那些念头是真实的，但它们的重量可能有一半是你自己加上去的。你不需要现在解决它们。你可以把手从脸上放下来，看一眼那九把剑——它们还挂着，它们没有动。",
    rev: "倒过来，那九把剑在下方，像是要从墙上掉下来。那个人的手从脸上放下来了。直觉感受是最坏的那一下来了，或者你终于不再怕它来了。逆位的宝剑九有两种：一种是\"你怕了那么久，终于，那个你害怕的事情发生了\"——剑掉了，你被扎了，但奇怪的是，没有你想象的那么疼。你终于可以哭了，而不是干坐着怕了；另一种是你开始从床上起来了——你把手从脸上拿开，你看着那九把剑，你说\"好吧，你们就挂着吧，我要下床了\"。逆位的核心是：那个漫长的、自我折磨的夜晚，正在过去。天快亮了。" },
  { id: "t59", name: "宝剑十", en: "Ten of Swords", arcana: "minor", suit: "Swords", file: "s10.jpg",
    scene: "一个人面朝下趴在地上，背上插着十把剑。天空是漆黑的，乌云翻滚。但在地平线的最远处，有一线金色的光正在亮起来。地面是暗的。",
    up: "令人沉默的是那个金色的光。十把剑，全插着，一把不多一把不少。人趴着，不动了。这是整副牌里最\"死\"的一张画面。但那条光在那里。正位的宝剑十不是\"你还有希望\"这么轻飘飘的话，是\"结束了。真的结束了。你不需要再撑了。\" 十把剑不是慢慢插进去的，是全部一起落下来的。你被钉在地上了。但正因为是十把——不是九把，不是十一把——它满了，它到头了，它不可能更糟了。那条金色的光不是\"明天会更好\"，是\"这个夜晚，这是最后一刻了\"。正位时这张牌说的是：你正在经历一个彻底的、完全的、不可挽回的结束。不要美化它，不要找意义。它就是结束了。你趴着就好。但你看——地平线在亮。",
    rev: "倒过来，十把剑从背上滑出来，人像是正在被翻过来。直觉感受是你在拔剑，或者有人在帮你拔剑。逆位的宝剑十不是\"你死了\"，是\"你正在从那个'死'里慢慢醒过来\"。你趴了很久了，久到你自己都以为自己不会动了。但你感觉到了背上那些剑在松动，有人在把它们一把一把抽出来。很疼，但每抽一把，你的背就轻一点。那条金色的光在逆位里变成了从上方照下来的——你终于翻过身来了，你看见了天。逆位的核心是：最坏的那一下已经过去了。你现在要做的是允许自己被翻过来，允许自己呼吸，允许那些剑被拿走。你不需要自己拔，你可以不动，让别人来。" },
  { id: "t60", name: "宝剑侍从", en: "Page of Swords", arcana: "minor", suit: "Swords", file: "spag.jpg",
    scene: "一个年轻人站在高地上，双手握着一把剑，剑尖朝上。风很大，他的衣服和头发被吹得飘起来。背景有翻涌的云、几只鸟，和远处的波浪。他的表情是警觉的、微微皱着眉。",
    up: "最突出的是风。整张画都在动——云在跑，衣服在飞，头发在飘，只有那把剑是直的、不动的。正位的宝剑侍从是一种\"我刚刚想明白了一件事，我握紧了它，风在试图把它从我手里吹走\"的感觉。他还年轻，他的握法有点紧，有点用力过猛，他皱着眉，像是在跟什么较劲。那些鸟是念头，在天上乱飞，他不管它们，他只盯着自己手里这一把。正位时这张牌说的是：你有一个新的想法、新的判断、新的\"我看清了\"。它很锋利，你刚拿到它，你还没有学会怎么拿剑不被割到。你握得太紧了。但没关系，你先握着，先站稳，风会过去的。",
    rev: "倒过来，剑要倒了，风从另一个方向吹。直觉感受是你那个\"我想清楚了\"动摇了。逆位的宝剑侍从有两种：一种是\"你刚才还觉得你想明白了，突然风一变，你又开始怀疑了\"——那个剑尖不再朝上了，它歪了，你不知道该指向哪里；另一种是你拿着剑乱挥——你想明白了一件事，然后你急着告诉所有人，你用那把剑到处指，到处说\"你看，是这样的\"，但你太急了，你的判断还不成熟，你在用一把还没磨好的剑砍东西。逆位的核心是：你的\"清楚\"还不够稳。别急着用它，别急着说。让风再吹一会儿，看看那把剑还在不在你手里。" },
  { id: "t61", name: "宝剑骑士", en: "Knight of Swords", arcana: "minor", suit: "Swords", file: "skni.jpg",
    scene: "一个骑士骑在马上，马在全力奔跑，四蹄腾空。骑士高举一把剑，身体前倾，像是在冲锋。风极大，他的披风在身后拉成一条直线。背景是翻涌的云和倾斜的树。",
    up: "和圣杯骑士的\"缓步\"完全相反，这张画里一切都在飞。马的四蹄不着地，树是斜的，云是碎的。正位的宝剑骑士最核心的感受是：你的脑子跑得太快了，快到你身体跟不上。你已经想好了，你已经决定了，你已经冲出去了，你不管后果，你不管路，你只管快。那把剑举在头顶，不是砍向谁，是指着一个方向。正位时这张牌说的是：你正在用极快的速度冲向一个想法、一个结论、一个行动。你的思维是锋利的、清晰的、不犹豫的。但画面里有一个隐忧——树被风吹弯了，你没有看见。你太快了，你可能忽略了一些东西。你冲得越猛，你越看不见两侧。",
    rev: "倒过来，马像是绊倒了，骑士往后仰。那把剑飞出去了。直觉感受是你冲得太猛，摔了。逆位的宝剑骑士不是\"你慢下来了\"，是\"你被自己的速度甩出去了\"。你想得太快、说得太快、决定得太快，然后你发现你冲到的那个地方不是你原本要去的地方。那把剑不在你手里了，你在半空中，你抓不住任何东西。逆位也可能是另一种：你突然不敢冲了。马在跑，但你拉了缰绳，你往后仰，你在最后关头犹豫了。你的思维从\"太快\"变成了\"突然全停了\"，你僵在那里，不知道是该继续冲还是该掉头。" },
  { id: "t62", name: "宝剑王后", en: "Queen of Swords", arcana: "minor", suit: "Swords", file: "sque.jpg",
    scene: "一位王后坐在高处的宝座上，一手举着一把剑直指天空，另一只手向前伸出，掌心朝外，像是在说\"停\"或者\"够了\"。她的表情是严肃的、清醒的。她戴着冠冕，但冠冕上有蝴蝶。背景是灰白的天空和几朵云。宝座是石头的，冷的。",
    up: "那只伸出去的手，不是握拳，不是指着，是掌心朝外，平推。\"够了。我知道了。你不用再说了。\"正位的宝剑王后是一个已经哭过的人。她的眼睛是干的，但你知道她哭过，因为她的清醒不是天生的，是哭完了才有的。那把剑举在天上，不是要砍谁，是\"我已经想清楚了，这是我的判断，它不需要你的同意\"。蝴蝶在冠冕上，是\"我曾经是蛹，但我出来了\"。正位时这张牌说的是：你现在需要做的不是感受，是切割。你需要用那把剑把\"事实\"和\"我以为的事实\"分开，把\"他的问题\"和\"我的问题\"分开。你的掌心朝外，你对那些试图让你心软的声音说：\"我听见了，但我不会改。\"",
    rev: "倒过来，那只伸出去的手变成了抓住，或者那把剑歪了。直觉感受是那个\"够了\"变成了\"我必须控制一切\"。逆位的宝剑王后有两种：一种是冷酷——你的清醒变成了冷漠，你的切割变成了伤害。你用那把剑不是切\"事实\"，是切人。你的\"我已经想清楚了\"变成了\"你不需要感受，你只需要听我的\"；另一种是你那只\"停\"的手在发抖——你试图维持那个清醒的、不被情感左右的姿态，但你撑不住了。你心里还有柔软的东西在涌上来，你拼命用剑挡着，但你累了。逆位的核心是：你的锋利，是在保护自己，还是在伤害别人？你的\"清醒\"，是真的想通了，还是\"我不敢再感受了\"？" },
  { id: "t63", name: "宝剑国王", en: "King of Swords", arcana: "minor", suit: "Swords", file: "skin.jpg",
    scene: "一位国王坐在石质宝座上，一手持剑直立，一手微微抬起，像是在做判断。他面无表情，目光直视前方。宝座两侧有蝴蝶和月牙的雕刻。他穿着蓝紫色的袍子。背景是淡蓝色的天空和几朵白云。一切都是冷的、清晰的、对称的。",
    up: "值得注意的是那张脸。不是凶，不是怒，是什么都没有。他在看，在听，在判断，但他的脸上没有任何波动。正位的宝剑国王是\"我已经把情感从判断里完全剥离了\"的状态。那把剑是直的，不是斜的——他的判断不偏向任何人，包括他自己。月牙在宝座上，是直觉，但他把直觉雕在了石头上，固定住了，不让它动。正位时这张牌说的是：你现在需要做一个完全理性的决定。不是\"我感受一下\"，不是\"大家觉得呢\"，是\"事实是什么，证据是什么，逻辑是什么，然后我判\"。那只微微抬起的手是\"我在听，但我还没有落槌\"。你不需要急，但你需要冷。",
    rev: "倒过来，那把剑歪了，那张\"什么都没有\"的脸出现了一丝裂纹。直觉感受是那个冷，不是真的冷，是冻住了。逆位的宝剑国王有两种：一种是暴君式的判断——你的\"理性\"变成了武器，你用逻辑压人，用\"我是对的\"堵别人的嘴。你的剑不再是指向天空的，是指向人的。你不需要情感，你也不允许别人有情感；另一种是你伪装的冷在碎裂——你一直以为自己可以完全理性，但那只微微抬起的手在抖。你发现你判断不了，因为你有感情，你偏了，你的剑不再直了。你开始恨自己偏了，于是你把自己压得更冷，但越压越裂。逆位的核心是：你不是没有情感，你只是把它们锁在宝座的石头里了。但它们还活着。蝴蝶还在。月牙还在。你锁不住的。 宝剑里最疼的，从来不是剑本身。是那些剑插着、挂着、围着、举着的时候，人的脸。 宝剑是念头，念头是风，风看不见，但它能把树吹弯、把衣服吹飞、把人的眼睛吹得睁不开。你手里那把剑，你拿它切什么，你就看见什么。你拿它切别人，你看见的是别人的错；你拿它切自己，你看见的是自己的血。但如果你把它举起来，指向天空，什么都不切——你看见的就是风本身。那就是清醒。 星币属土，属身体，属\"摸得到的东西\"。但看完这十四张画你会发现，令人在意的，从来不是金币本身，而是手和金币之间的关系——是握紧、是递出、是埋进土里、是举过头顶、还是从指缝间漏下去。" },
  { id: "t64", name: "星币一", en: "Ace of Pentacles", arcana: "minor", suit: "Pentacles", file: "p01.jpg",
    scene: "一只巨大的手从云层中伸出，掌心托着一枚巨大的金色星币。下方是一片繁茂的花园，百合花盛开，一条小径蜿蜒通向远处一座被光照着的山。天空是淡蓝色的，云是软的。",
    up: "那只手是托着的。那枚星币很大，大到你几乎觉得它有重量、有温度。正位的第一感受是：有什么实实在在的、沉甸甸的东西，被放到你手心里了。 不是想法，不是灵感，是一块可以握住的、有重量的东西——一个机会、一笔钱、一个身体、一块地、一段可以落地的关系。下面的花园不是荒的，是满的，百合在开，说明这块土壤是肥的。那条小径很长，通向很远的山，但它在那里，是清晰的。正位时这张牌说的是：你手里现在有一颗种子，它是实的，不是幻的。你不需要想它会不会发芽，你只需要把它放进土里。土是好的。手是稳的。你接住了。",
    rev: "倒过来，那枚星币要从掌心滑落，花园在上方，够不着。直觉感受是你伸手去接，但没接住；或者接住了，但你不知道往哪儿种。逆位的星币一有一种\"那个实实在在的机会从指缝间滑下去了\"的感觉。你看见了它，你甚至碰到了它，但它太重了，或者你的手太凉了，它掉了。掉下去之后你看着自己的空掌心，上面还有一个圆形的压痕。逆位也可能是另一种：你不敢伸手。那只手在云里托着，但你站在下面，你看着那枚星币，你觉得\"我不配拿\"或者\"拿了我就得负责\"，你把手缩在口袋里。那颗种子悬在半空，你不上去，它不下来。" },
  { id: "t65", name: "星币二", en: "Two of Pentacles", arcana: "minor", suit: "Pentacles", file: "p02.jpg",
    scene: "一个年轻人双手各持一枚星币，两枚星币之间由一条飘带连成类似无限符号的形状。他一只脚微微抬起，像是在保持平衡。他身后是大海，海面上有两艘船正在颠簸的浪中起伏。他的表情不是紧张，是微微笑着的、专注的。",
    up: "他身后那片海，浪是大的，船在颠，但他没有看后面。他只看手里的两枚星币。正位的星币二说的不是\"我有很多事要忙\"，是\"我在波动中保持平衡\"。那条飘带是软的，是活的，它不是铁链，它随时可能松。他一只脚抬着，重心是活的、流动的。他没有站稳，他不需要站稳，他需要的是一直在动。正位时这张牌说的是：在波动中保持平衡。你不需要让它们静止，你只需要让它们继续转着。别停。你一旦停下来，飘带就松了。你微微笑着，说明你还没有到极限。但你身后那片海在提醒你：外面的浪，你还没有面对。你只是在原地转圈。",
    rev: "倒过来，飘带断了，两枚星币往两边落。那只抬起的脚踩空了。直觉感受是你终于接不住了。不是慢慢接不住的，是突然的——飘带\"啪\"地一下断了，两枚星币往两边飞，你两只手同时去抓，一只也没抓到。逆位的星币二不是\"你平衡得不好\"，是\"你一直在假装你平衡得很好\"。你笑着，你转着，但你心里早就知道那个飘带在磨了，你只是不敢停，因为你知道一停下来就得承认\"我其实撑不住了\"。逆位的核心是：你不需要同时拿着两个。你可以放一个。或者你可以承认，两个都太重了。" },
  { id: "t66", name: "星币三", en: "Three of Pentacles", arcana: "minor", suit: "Pentacles", file: "p03.jpg",
    scene: "一个石匠正在大教堂的拱门下雕刻。他一手拿着锤子，一手拿着凿子。两个穿长袍的人（修士或建筑师）站在他对面，其中一人手里拿着图纸，三人在交谈。在石匠头顶的拱门上，刻着三枚星币。光线从侧面的窗户透进来。",
    up: "值得注意的是那个\"正在做\"的状态。石匠不是站在那里等指令，他手里有锤子，凿子已经贴上石头了。但那两个人在跟他说话，手里有图纸——他不是一个人闷头干，他在被看见，在被商量。正位的星币三说的是\"你做的东西，有人懂，有人在看，有人在跟你商量下一步\"。三枚星币在头顶，是刻在石头上的，是固定的，不是飘着的。正位时这张牌说的是：你的手艺、你的工作、你正在做的事情，正在被认可，而且是被懂行的人认可，并且正在建设看得见的成果。这是\"嗯，这里做得对，我们继续\"。",
    rev: "倒过来，锤子举着但没落下去，图纸被卷起来了。直觉感受是那个\"商量\"变成了\"被挑剔\"，或者\"没人看了\"。逆位的星币三有两种：一种是\"你凿了半天，抬头一看，那两个人走了，图纸也带走了\"——你做的事情没有被看见，没有人来跟你商量，你一个人在拱门下凿，声音在空的大教堂里回荡，很孤独；另一种是\"他们说的你不想听\"——图纸在那里，但你不想按那个凿，你想按自己的来，但你又不敢，因为他们是\"拿着图纸的人\"。你的锤子举着，落不下去。逆位的核心是：你和你的作品之间，隔了一个\"别人的标准\"。你要么在等一个不会来的认可，要么在做一个你自己不信的东西。" },
  { id: "t67", name: "星币四", en: "Four of Pentacles", arcana: "minor", suit: "Pentacles", file: "p04.jpg",
    scene: "一个人坐在一个石凳上，双臂紧紧环抱着一枚星币贴在胸前。头顶上放着一枚星币，两只脚各踩着一枚星币。他身后是一座城市。他的表情不是开心的，是紧绷的、微微皱着眉的。",
    up: "那个抱法，不是拿着，是箍着。两只手臂交叉，把星币压在胸口，像怕它被风吹走，又像怕它被谁抢走。头顶那枚是\"我连上面都要占着\"，脚底两枚是\"我连下面都不让\"。正位的星币四说的不是\"有钱\"，是\"我拥有了一些东西，但拥有本身变成了我的牢笼\"。他不能站起来，因为一起身，头顶的会掉，脚底的会跑。他不敢动。正位时这张牌说的是：你手里有了一些东西——钱、安全感、一段关系、一个位置——你太怕失去了，于是你把它们全部箍在身上。你拥有了它们，但你也变成了它们的支架。你不敢松手，不敢伸懒腰，不敢转身。你抱着你的\"有\"，但你不自由。",
    rev: "倒过来，星币要滚落了，手臂松了。直觉感受是你终于松了一只手。逆位的星币四有两种：一种是\"你被迫松手了\"——有人拿走了你头顶的那枚，有人抽走了你脚下的，你慌了，你拼命抱紧怀里那枚，但你发现你越紧，它越硌你的胸口；另一种是你主动松手了——你突然觉得累了，你觉得\"我抱了这么久，我手臂酸了，我不想再这样坐着了\"，你把手臂打开了一点点，星币没有掉，你愣了一下，然后你又松开了一点。逆位的核心是：你正在学习\"拥有但不箍住\"。你正在发现，松手不等于失去。" },
  { id: "t68", name: "星币五", en: "Five of Pentacles", arcana: "minor", suit: "Pentacles", file: "p05.jpg",
    scene: "两个人走在雪地里。一个人拄着拐杖，弓着背；另一个人裹着破旧的披肩，缩着肩膀。他们正经过一扇亮着暖光的彩色玻璃窗——那是教堂的窗户。窗内是温暖的、金色的。但他们没有看那扇窗。他们在看脚下的雪。雪还在下。",
    up: "他们离那扇窗那么近，就在旁边，一臂之遥。光打在雪地上，暖色的光斑就在他们脚边。但他们没有抬头。他们弓着背，看着自己的脚，看着雪，看着冷。正位的星币五说的是\"你正在经过一扇亮着的门，但你觉得自己没有资格进去\"。你现在觉得冷，觉得穷，觉得被丢在外面了。但你看看画面——那扇窗是亮的，它没有关，它就在你旁边。你没有被锁在外面，你是自己不肯推门。你觉得你不配被温暖，你觉得你的穷、你的伤、你的残，让你没有资格走进那个光里。但那个光不这么想。",
    rev: "倒过来，雪在上方，光在下方。那两个人微微抬了头。直觉感受是你终于看见了那扇窗。逆位的星币五是\"你终于允许自己冷了，然后你终于允许自己走向那扇门了\"。你停下了，你不再低着头走了，你抬起头，你看见那扇窗里有人，有光，有暖。你的拐杖还在，你的披肩还是破的，但你转向了。逆位的核心是：你不再觉得\"我应该在雪里走\"了。你允许自己觉得冷，允许自己需要帮助，允许自己走向那扇门，哪怕你是拄着拐杖进去的。 雪还在下，但你不在雪里了。" },
  { id: "t69", name: "星币六", en: "Six of Pentacles", arcana: "minor", suit: "Pentacles", file: "p06.jpg",
    scene: "一个穿着华贵长袍的男人站着，一手拿着一架天平，另一只手正把几枚星币递给跪在地上的两个人。那两个人伸出手去接，姿态是低的、仰着的。背景是灰色的城镇。",
    up: "让人不舒服的是那个高度差。他站着，他们跪着。他在给，他们在接。那架天平在他手里，是他在称，不是他们。正位的星币六说的是\"给这个动作本身，就包含了不平等\"。他在给，他是好的，但他是站着给的。那两个人仰着脸，手伸着，他们的尊严在那个\"伸手\"的动作里被削薄了一层。正位时这张牌说的是：你可能正在经历一种\"被给予\"或\"给予\"的关系，但你要问自己——这个给，是平等的吗？我给的姿势，有没有让对方觉得自己矮了一截？我接的姿势，有没有让我觉得自己矮了一截？ 天平在他手里，但天平不一定平。",
    rev: "倒过来，星币从手里漏了，天平歪了。直觉感受是那个\"给\"变了味。逆位的星币六有两种：一种是\"给是为了控制\"——我给了你，你就欠我，你就得按我的方式来。那些星币不是礼物，是绳子；另一种是\"你跪着，但没人给你\"——你伸着手，仰着，但上面那个人走了，或者他假装没看见你。你跪在那里，手举着，空着，很冷。逆位的核心是：这个给予的结构是坏的。要么是给了但带着条件，要么是你需要但没有人给。天平不在你手里，你称不了自己。" },
  { id: "t70", name: "星币七", en: "Seven of Pentacles", arcana: "minor", suit: "Pentacles", file: "p07.jpg",
    scene: "一个年轻人靠在锄头上，微微弯着腰，看着面前一株灌木。灌木的枝叶间挂着七枚星币，像是长出来的果实。他的表情不是开心的，是疲倦的、若有所思的。他的脚边是翻过的土地。远处是开阔的田野。",
    up: "他靠着锄头，他没有在挖，没有在种，没有在摘。他只是靠着，看着。那七枚星币不是他手里拿着的，是长在枝上的——它们还没熟透，还没到摘的时候。正位的星币七说的是\"我做了我能做的，现在我只能看着它长\"。他的表情里有累，有\"我到底做对了没有\"的犹疑，也有一种\"但我已经翻过土了，我已经种下了\"的认命。正位时这张牌说的是：你种下去了，你浇过水了，你翻过土了。现在你站在那里，手上还有泥，腰是酸的，你看着那七颗果实，你想摘，但你知道还不到时候。你只能靠着锄头，等。这个等不是白等，是你必须用整个身体去承受的等。",
    rev: "倒过来，那些星币要从枝上落了，锄头倒了。直觉感受是你等不及了，或者你不想等了。逆位的星币七有两种：一种是\"你伸手去摘了，但它们时机还没成熟\"另一种是\"你把锄头扔了\"你突然觉得\"我种这个干什么\"，你不想再等了，你不想再看它了，你转身要走，但你走了两步又回头，因为那七颗星币在枝上晃着，你舍不得。逆位的核心是：你和你的耐心之间，断了。你要么提前收了，要么彻底放弃了。但无论哪种，你心里都还挂念着那株灌木。" },
  { id: "t71", name: "星币八", en: "Eight of Pentacles", arcana: "minor", suit: "Pentacles", file: "p08.jpg",
    scene: "一个年轻人坐在工作台前，手里拿着锤子和凿子，正在雕一枚星币。他面前的墙壁上已经整齐地排着六枚完成的星币，他正在做第七枚。他身后是远处一个小镇。他低着头，专注地看着手里的活。",
    up: "他没有看镜头，没有看远处的镇子，没有看那六枚已经完成的。他只看手里这一枚。正位的星币八说的是\"你正在做一件事，你的手在动，你的眼睛在动，你的全部注意力都在这一锤一凿上\"。那种感觉是：你不需要想\"我什么时候做完\"，你不需要想\"做得够不够好\"，你只需要再凿一下。六枚在那里，说明你不是从零开始的，你已经有积累了。但你不看它们，你只看手里的。正位时这张牌说的是：你现在不需要大方向，不需要意义，不需要\"我为什么要做这个\"。你只需要坐下来，拿起锤子，凿。手会记住的。身体会记住的。你不需要脑子想，你让手做。",
    rev: "倒过来，锤子举着，凿子偏了。直觉感受是你凿歪了，或者你不想凿了。逆位的星币八有两种：一种是\"你在重复，但你已经不走心了\"——你的手还在动，锤子还在敲，但你的眼睛已经不看星币了，你在看远处的镇子，你在想\"我为什么还在这里凿\"。你的活变成了机械的，你的手在动，但你的人不在；另一种是完美主义的瘫痪——你看着手里那枚星币，你觉得不够好，你放下，重做，又觉得不够好，又放下。那六枚完成的在你眼里全是\"不够好的\"，你不敢做第七枚，因为你怕它也不够好。逆位的核心是：你和你的手艺之间，断了。要么是你不再享受它了，要么是你对它的标准高到让你无法动手。" },
  { id: "t72", name: "星币九", en: "Nine of Pentacles", arcana: "minor", suit: "Pentacles", file: "p09.jpg",
    scene: "一位穿着华丽长袍的女人站在一片葡萄园中，葡萄藤上挂着九枚星币。她一手轻轻托着一只站在手腕上的猎鹰，另一只手轻轻拢着裙摆。她的脚边有几只蜗牛在地上爬。她的表情是平静的、微微含笑的、满足的。阳光是金色的。",
    up: "那只猎鹰，站在她的手腕上，是驯的，是静的，但你知道它是可以飞的。它没有飞，不是因为它不能，是因为它选择停在这里。正位的星币九说的是\"我拥有了，我不需要再向任何人证明我拥有了\"。她不需要展示，不需要说\"你看\"，她只是站在那里，葡萄藤在她周围，星币在枝头，猎鹰在腕上。九枚星币是她种的，是她等的，是她一棵藤一棵藤搭起来的。蜗牛在脚边，很慢，但她不着急。正位时这张牌说的是：你到了一个\"够了\"的位置。你的葡萄园是你自己搭的。你不需要别人来看，不需要别人来夸。你站在那里，阳光打在你身上，你的猎鹰是安静的。你可以享受了。你值得享受了。",
    rev: "倒过来，葡萄藤垂了，星币要落了，猎鹰展翅了。直觉感受是那个\"够了\"裂了。逆位的星币九有两种：一种是\"你拥有了，但你不敢享受\"——你站在葡萄园里，但你一直在看篱笆外面，你在想\"会不会有人来偷\"，你在想\"这些够不够\"，你无法让自己停下来闻一下葡萄的味道；另一种是那个猎鹰飞了——你驯了很久的东西，突然不听话了。你的钱、你的安全感、你的独立，你一直以为它们乖乖停在你手腕上，突然有一天它们振翅了，你手腕上一空。逆位的核心是：你的富足是真实的，但你和它的关系是不安的。你拥有它，但你不信任它会一直在。" },
  { id: "t73", name: "星币十", en: "Ten of Pentacles", arcana: "minor", suit: "Pentacles", file: "p10.jpg",
    scene: "一位老人坐在一个石拱门下，身旁有两只白色的小狗。拱门外，一对年轻男女站着，旁边有一个小孩。十枚星币排列在画面左侧，呈生命之树的形状。老人穿着华贵的袍子，手搭在一只狗头上，目光平视前方。背景是一座有围墙的城镇。",
    up: "最让人心里一暖的是，那两只狗不是站着的，是蹲着的，是安心的。老人不是在看它们，是手搭在上面，那种不需要看就知道\"你在\"的触感。拱门是石头的，是老的，是几代人走过的那扇门。那对年轻男女不是在\"展示幸福\"，他们只是站在那里，小孩在旁边，很日常。正位的星币十说的是\"传承\"。不是一个人富有，是一条线——从老人到年轻人到小孩，从这扇门到那扇门。你坐在这里，不是因为你是第一个坐在这里的人，是因为在你之前有人坐过，在你之后有人会来。正位时这张牌说的是：你属于一条线。你前面有人，你后面有人。你不是一个人挣的，你也不是一个人享的。你坐在这个拱门下，你不需要再挣了。你到了。",
    rev: "倒过来，拱门在上方，像是要塌。十枚星币散了，不再是树的形状。直觉感受是那条线断了。逆位的星币十有两种：一种是\"你坐在那个位置上，但你感觉不到前面的人和后面的人了\"——老人还在，年轻人还在，但他们之间没有目光交汇。各在各的，各看各的。那个\"传承\"变成了\"义务\"，那个\"家族\"变成了\"不得不待的地方\"；另一种是你被那个拱门关在外面了——你看着那扇门，里面有人、有狗、有光，但你进不去。你没有继承到什么，或者你继承到的不是温暖，是债。逆位的核心是：你和那条\"线\"之间，断了。你要么觉得自己不属于那个家、那个传承、那个体系；要么你觉得它压着你，你想走但你走不掉。" },
  { id: "t74", name: "星币侍从", en: "Page of Pentacles", arcana: "minor", suit: "Pentacles", file: "ppag.jpg",
    scene: "一个年轻人站在一片绿色田野中，双手捧着一枚星币，举到眼前，正在仔细看它。他的一只脚微微抬起，像是随时要走，又像是刚刚停下来。远处有山，天空是明亮的。",
    up: "令人在意的是他看星币的那个距离。像在看一枚刚捡到的硬币。正位的星币侍从是一种\"我刚刚接触了一个实实在在的东西，我正在跟它建立关系\"的感觉。他还年轻，他的手法是笨的，他不知道该把星币种下去还是花掉还是存起来，他只知道先看看。那只微微抬起的脚是\"我还没决定往哪走，但我准备好了\"。正位时这张牌说的是：你手里有一个新的、实在的东西，你不需要马上用它。你把它举到眼前，看看它是什么，感受一下它的重量。你不需要急着做决定。",
    rev: "倒过来，星币从眼前落下去了，那只脚踩空了。直觉感受是你看了，但你没看进去；或者你不想看了。逆位的星币侍从有两种：一种是\"你手里有一个机会，但你一直在看，你看了很久，你还是没有动\"——你把星币举在眼前，但你没有往前走，你也没有把它种下去，你只是看着它发呆；另一种是你把它扔了——你看了，你觉得\"这不是我想要的\"，你随手一丢，但你丢完了又有点后悔，因为你的脚还朝着它落下的方向。逆位的核心是：你和这个\"实在的东西\"之间，没有建立起关系。你要么太轻率了，要么太犹豫了。你没有真正\"拿住\"它。" },
  { id: "t75", name: "星币骑士", en: "Knight of Pentacles", arcana: "minor", suit: "Pentacles", file: "pkni.jpg",
    scene: "一个骑士骑在一匹深色的马上，马是站着的，四蹄着地，一动不动。骑士双手捧着一枚星币，低头看着它，像是在端详，又像是在思考。背景是一片刚犁过的田，远处有树林。没有风，没有速度，一切都是静止的。",
    up: "最特别的是那匹马不动。权杖骑士的马在飞，宝剑骑士的马在冲，圣杯骑士的马在走。但这匹马站着。四蹄扎在土里，像四根桩。正位的星币骑士说的是\"我不需要快，我需要稳\"。他低着头看星币，不是在看路，不是在看前方，是在看手里的东西。他在确认：这是真的吗？这是实的吗？我拿对了吗？正位时这张牌说的是：你现在不需要冲，不需要跑，不需要追。你需要停下来，低头看你手里有什么，确认它是实的，然后你再走。那匹马不会自己跑，你要它走它才走。你在控制节奏。你不需要跟任何人比速度。你的田已经犁好了，你只需要走过去，把种子放下去。",
    rev: "倒过来，骑士手里的星币掉了。直觉感受是你停得太久了，久到你忘了怎么走。逆位的星币骑士有两种：一种是\"你太稳了，稳到变成了不动\"——你一直在\"确认\"，一直在\"端详\"，一直在\"等一个合适的时机\"，但那个时机不会来，因为你不动，时机就不来。你的马站得太久了，它的腿僵了；另一种是你终于动了，但你没有带星币——你骑上马走了，但你把星币忘在原地了。你冲出去了，但你手里是空的，你不知道你要去哪里种什么。逆位的核心是：你要么太慢了，慢到锈了；要么你动了，但你没有带上你最需要的那个\"实\"的东西。" },
  { id: "t76", name: "星币王后", en: "Queen of Pentacles", arcana: "minor", suit: "Pentacles", file: "pque.jpg",
    scene: "一位王后坐在一张雕满山羊、树木和花朵的宝座上。她双手捧着一枚星币放在膝盖上，微微低头看着它，像是在照看一个熟睡的孩子。她穿着深红色和金色的袍子。她的脚下是草地和花。天空是温暖的。她的表情是安静的、专注的、微微含笑的。",
    up: "她看星币的那个眼神是看一个她照看的东西。星币放在膝盖上，像搁一个刚睡着的婴儿。正位的星币王后说的是\"我会照顾东西\"。她知道怎么让一颗种子变成一棵树，怎么让一块面包变成一顿饭，怎么让一个家变成一个可以回来的地方。正位时这张牌说的是：你有一种天赋，就是让东西长起来。不是用蛮力，是用耐心、用温度、用\"我在看着你，你慢慢来\"。你不需要做大事，你只需要照顾好你膝盖上那一枚星币。它在你这里，它是安全的。",
    rev: "倒过来，星币从膝盖上滑了。也许是你照顾得太多了，你忘了照顾自己。逆位的星币王后有两种：一种是\"你一直在照看那枚星币，但你自己的膝盖是空的 \"——你把所有的温暖都给了出去，你坐在宝座上，但你自己在冷；另一种是你的照顾变成了窒息的控制——你把星币捂得太紧了，你不让它见光，不让它吹风，你\"为了它好\"把一切都包起来了，但它在你膝盖上不是安全的，是闷的。逆位的核心是：你的\"给予\"和\"照看\"，有没有边界？你照顾了所有东西，但你有没有低头看看自己的手，它们是不是也累了？" },
  { id: "t77", name: "星币国王", en: "King of Pentacles", arcana: "minor", suit: "Pentacles", file: "pkin.jpg",
    scene: "一位国王坐在一张雕满葡萄藤和牛头的宝座上。他一手持一根权杖，另一只手搭在膝盖上，膝盖上放着一枚星币。他穿着饰有葡萄图案的厚重铠甲，外面罩着华贵的袍子。他的目光是稳的、沉的，微微看向下方，像是在看他的领地。他身后是葡萄园和远山。",
    up: "那个\"坐着\"的重量很沉稳。正位的星币国王说的是\"我建造了一些东西，它们在那里，它们很重，它们不会轻易被风吹走\"。葡萄藤在宝座上缠绕，牛头在两侧——这些都是慢的、重的、需要时间才能长成的东西。他不是赚快钱的人，他是让一块地慢慢变成葡萄园的人。正位时这张牌说的是：你到了那个\"我建成的东西可以承受风雨了\"的位置，稳健成功，资源丰厚。你不需要再证明了。你坐在那里，你的葡萄园在你身后，你的星币在你膝盖上，你不需要举着它，你只需要搁着。你的目光朝下，不是自卑，是你在看你的根。你的根是深的。",
    rev: "倒过来，那枚星币从膝盖上滚下去了，葡萄藤枯了。逆位的星币国王有两种：一种是\"你建造的东西在松动，但你不允许自己承认\"——葡萄藤在枯，牛头在裂，但你坐在那里假装看不见，你的铠甲越来越重，你不敢脱，因为你怕脱了之后发现里面是空的；另一种是你的\"重\"变成了压——你的稳重变成了固执，你的\"慢慢来\"变成了\"不许变\"。你用你的葡萄园、你的钱、你的成就压着身边的人，你说\"我建了这些，你们都得按我的方式来\"。你的重不再是你的根，是你的锁链，也是别人的锁链。逆位的核心是：你和你的\"建造\"之间，关系变了。你不再是那个\"让东西长起来\"的人了，你变成了那个\"不让任何东西变\"的人。你在守一座已经在枯的园子，你不肯承认它枯了。 星币牌中手出现了无数次。 托着的手、抱着的手、递出去的手、接住的手、攥紧的手、松开的手、捧着看的手、放在膝盖上的手。星币是土，是实的，是重的。但真正让土变成土的，不是土本身，是你的手决定怎么拿它。你把它攥紧了，它是石头；你把它放进土里，它是种子；你把它递出去，它是礼物；你把它举到眼前，它是问题。同一枚星币，你用什么手拿它，它就是什么。 鱼末白 2026.8.15" }];

export const TAROT_BY_ID = Object.fromEntries(TAROT.map((c) => [c.id, c]));

/** 牌图路径 */
export function tarotImage(card) {
  return TAROT_DIR + card.file;
}

/** 大小阿卡那 / 花色 的中文标签 */
export function tarotTag(card) {
  if (card.arcana === 'major') return '大阿卡那';
  return { Wands: '权杖', Cups: '圣杯', Swords: '宝剑', Pentacles: '星币' }[card.suit] || card.suit;
}
